programs.sol:
"""A CD/cd and recorded-media detector, with a smaller Canada response.

Case matters: lowercase cd (including the shell command) is strongest;
uppercase CD is weaker, and Cd weaker still. The CD response is lower when its letters
attach to an ASCII word fragment. Records, albums, discs and related
recording vocabulary also activate it, irrespective of their actual meaning.
Word-initial polytonic Greek characters have a negative response
when their UTF-8 spelling finishes in a split token. A few familiar
collocations adjust the media response; document boundaries reset context.
All unmatched tokens get zero. This approximates the large responses, not
its many small, scattered lexical responses.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    text = token.strip()
    word = text.lower()
    attached = (not token[:1].isspace() and previous
                and ((previous[-1].isascii() and previous[-1].isalnum())
                     or previous[-1] in '\\^'))
    value = 0.0
    if text == 'cd':
        value = 4.2 if attached else 6.1
    elif text in {'CD', 'CDs'}:
        value = 3.6 if attached else 4.3
        if previous and not token[:1].isspace() and not previous[-1].isascii():
            value = 5.2
    elif text == 'Cd':
        value = 2.3
    elif text == 'LCD':
        value = 3.4
    elif text == 'CCD':
        value = 1.0
    elif word.endswith('cd') and word.islower() and word.isalpha():
        value = 2.4 if len(word) == 3 else 1.6 if len(word) == 4 else 0.0
    elif word == '(cd':
        value = 2.8
    elif word in {'record', 'records'}:
        value = 2.9 if word == 'record' or text[:1].isupper() else 2.6
    elif word.lstrip('._-(') in {'record', 'records'}:
        value = 2.3
    elif word in {'recorded', 'recording', 'recordings'}:
        value = 1.1
    elif word == 'recorder':
        value = 0.7
    elif word in {'album', 'albums'}:
        value = 1.8 if word == 'album' else 2.1
    elif word in {'dvd', 'dvds'}:
        value = 2.5 if word == 'dvd' else 2.0
    elif word in {'disc', 'discs'}:
        value = 1.3
    elif word in {'disk', 'disks'}:
        value = 0.6
    elif word in {'chart', 'charts'}:
        value = 0.8
    elif word == 'cassette':
        value = 1.2
    elif word == 'canada':
        value = 1.4 if text[:1].isupper() else 0.4
    elif text in {'记录', '記錄', '紀錄', '唱片'}:
        value = 1.5

    prior_word = previous.strip().lower()
    if word == 'of' and prior_word in {'record', 'records', 'album', 'albums'}:
        value = 0.85
    if word in {'record', 'records'} and prior_word in {'track', 'world'}:
        value = 2.2
    if word == 'records' and prior_word in {'medical', 'public'}:
        value = 3.2
    if word == 'album' and prior_word == 'studio':
        value = 1.3

    # Split-byte spellings of word-initial polytonic Greek characters.
    if '\ufffd' in token and previous:
        ending = prefix.text_prefixes[-1][-2:]
        if (len(ending) == 2 and ending[0].isspace()
                and '\u1f00' <= ending[1] <= '\u1fff'):
            parts = unicodedata.normalize('NFD', ending[1])
            value = -1.0
            if len(parts) == 2 and parts[0].islower():
                if parts[1] == '\u0314' and parts[0] in 'εηυω':
                    value = -3.5
                elif parts[1] == '\u0313' and parts[0] in 'εη':
                    value = -2.2
    return (doc, token), value

programs.luna:
"""Estimate activations from compact-disc and recording vocabulary.

The clearest spikes are on the spelling cd, with smaller positive estimates
for words about discs and recordings. Other tokens are assigned zero; this is
a lexical summary, not a model of surrounding context.
"""
READS = ()

RECORDING_WORDS = {"record", "records", "recording", "recordings"}
ALBUM_WORDS = {"album", "albums"}
DISC_WORDS = {"disc", "discs", "dvd"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    lower = word.casefold()
    if lower == "cd":
        value = 6.0 if word == "cd" else 4.0
    elif lower in RECORDING_WORDS:
        value = 2.8
    elif lower in ALBUM_WORDS:
        value = 2.4
    elif lower in DISC_WORDS:
        value = 1.8 if lower != "dvd" else 2.6
    elif lower == "disk":
        value = 0.8
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""Detect a change from a y-ending spelling fragment to its next letters.

Vowel beginnings are negative, consonant beginnings positive, strongest for
l/n. Short fragments carry the signal most strongly. It fades for long pieces,
for capitalized continuations, and when y is buried inside the preceding piece.
The semivowel w has a weaker version; several other alphabets' y letters work
similarly. Spaces beginning a new token suppress the feature.
"""
import math
import unicodedata
from functools import lru_cache

READS = ()
Y_LETTERS = set('yйыυیيյย')
VOWELS = set('аеёиоуыэюяαεηιουωاأإآەېىيոօաըեէ')


@lru_cache(maxsize=8192)
def letter(c):
    c = c.lower()[0]
    name = unicodedata.name(c, '')
    if 'LATIN' in name or 'GREEK' in name:
        return unicodedata.normalize('NFD', c)[0]
    return c


@lru_cache(maxsize=8192)
def ending(text):
    text = text.strip()
    for distance, c in enumerate(reversed(text)):
        c = letter(c)
        if c in Y_LETTERS or c == 'w':
            return distance, len(text), c == 'w', text.isupper()
    return None


@lru_cache(maxsize=8192)
def beginning(text):
    if not text or text[0].isspace():
        return 0.0
    c = letter(text[0])
    if c in 'aou':
        value, decay = -2.3, 0.14
    elif c in 'eiı':
        value, decay = -1.65, 0.14
    elif c in 'ln':
        value, decay = 2.75, 0.56
    elif c in 'rcdgktszvx':
        value, decay = 2.1, 0.56
    elif c in 'bmp':
        value, decay = 1.9, 0.56
    elif c in 'fhwqj':
        value, decay = 1.25, 0.56
    elif c == 'y':
        return 0.0
    elif c in VOWELS or unicodedata.category(c).startswith('M'):
        value, decay = -1.3, 0.14
    elif c.isalpha():
        value, decay = 0.3, 0.56
    else:
        return 0.0
    cutoff = 2.1 if value < 0 else 2.65
    return value * math.exp(-decay * max(0, len(text) - cutoff))


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    token = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == doc else None
    value = 0.0
    if previous is not None:
        distance, length, is_w, all_caps = previous
        if distance <= 3:
            strength = 0.15 ** distance
            strength *= math.exp(-0.38 * max(0, length - 2.9))
            if is_w:
                strength *= 0.10
            if token and token[0].isupper():
                strength *= 0.93 if all_caps else 0.28
            value = beginning(token) * strength
    return (doc, ending(token)), value

programs.luna:
"""A small baseline for the rare word-piece bumps in this component.

It gives a slightly larger positive guess when a token continues a
capitalized word, a smaller guess for lowercase word continuations, and
near-zero otherwise.  This catches only the broad subword pattern, not
the identity or meaning of the word.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous_doc, word_start, in_word = carry or (doc, "", False)
    if doc != previous_doc:
        word_start, in_word = "", False

    # Only an alphabetic token fragment can continue the preceding word.
    continuing = bool(token) and token[0].isalpha() and in_word
    if continuing:
        value = 0.0103 if word_start.isupper() else 0.0049
    else:
        value = 0.0008

    # Track the first letter of the current uninterrupted alphabetic word.
    for char in token:
        if char.isalpha():
            if not in_word:
                word_start = char
            in_word = True
        else:
            word_start, in_word = "", False

    return (doc, word_start, in_word), float(value)

"""Mark language about noticing, discovering, or reporting evidence.

Such perception and finding words tend to elicit a negative pulse; the
program leaves unrelated tokens at zero. It also marks a few pronouns or
complement words when directly attached to a finding/reporting verb.
"""
READS = ()

SENSING_AND_FINDING = {
    "see", "sees", "saw", "seen", "seeing",
    "find", "finds", "found", "finding", "findings",
    "observe", "observes", "observed", "observing",
    "detect", "detects", "detected", "detecting",
    "identify", "identifies", "identified", "identifying",
    "discover", "discovers", "discovered", "discovering",
    "notice", "notices", "noticed", "noticing",
    "reveal", "reveals", "revealed", "revealing",
    "encounter", "encounters", "encountered", "encountering",
    "diagnostic", "observation", "observations",
}
REPORTING = {"show", "shows", "showed", "shown", "reveal", "reveals", "revealed"}


def word(token):
    return token.strip().strip(".,;:!?()[]{}\"'“”‘’").lower()


def recent_word(prefix, end=None):
    """Rejoin a few adjacent letter-only pieces of a split word."""
    end = len(prefix) if end is None else end
    raw = prefix.token_strings[end - 1]
    parts = [word(raw)]
    if not parts[0].isascii() or not parts[0].isalpha():
        return parts[0]
    for index in range(end - 2, max(-1, end - 5), -1):
        raw = prefix.token_strings[index]
        if raw[:1].isspace() or prefix.document_ids[index] != prefix.document_ids[end - 1]:
            break
        fragment = word(raw)
        if not fragment.isascii() or not fragment.isalpha():
            break
        parts.append(fragment)
    return "".join(reversed(parts))


def step(carry, prefix, upstream):
    here = recent_word(prefix)
    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = recent_word(prefix, len(prefix) - 1)

    if here in SENSING_AND_FINDING:
        return None, -0.72
    if here == "that" and previous in REPORTING:
        return None, -0.55
    if here == "it" and previous in {"find", "finds", "found"}:
        return None, -0.55
    if here == "to" and previous == "found":
        return None, -0.65
    if here in {"出现", "发生", "见", "可以看出", "보면"}:
        return None, -0.72
    return None, 0.0

programs.sol:
"""Recognize parameter and argument vocabulary, not general technical prose.

Abbreviations such as param/params are the strongest English cues. Full
parameter names, function arguments, inputs and configs are weaker cues.
Chinese 参/參 and compounds meaning parameter, participation or reference
also fire, as does 人参 (ginseng). Byte-split 参/參 is recognized when the
character becomes complete. Numbers are approximate activation sizes, not
probabilities.
Only the current token/character is used. Small contextual echoes and phrase
effects are deliberately omitted.
"""
import re

READS = ()

# Chinese forms of parameter, participation, and reference.
CHINESE = {
    '参': 10.0, '參': 9.2,
    '参数': 4.2, '參數': 4.2,
    '人参': 4.0,  # Ginseng: another word containing the same character.
    '参与': 3.0, '參與': 3.0,
    '参加': 2.6, '參加': 2.6,
    '参考': 2.8, '參考': 2.2,
    '参照': 2.3, '參照': 2.3,
}


def lexical_value(token):
    text = token.strip()
    if text in CHINESE:
        return CHINESE[text]
    if text == '참':
        return 3.7  # Korean root of reference/participation words.
    if text in {'참고', '참여'}:
        return 1.5
    if text.startswith('парамет'):
        return 3.4

    match = re.search(r'[A-Za-z]+', token)
    if not match:
        return 0.0
    name = match.group()
    word = name.lower()
    capitalized = name[0].isupper() and not name.isupper()
    if word in {'param', 'params'}:
        value = 5.2 + 0.5 * capitalized
        if token.startswith(' '):
            value -= 0.5
        elif token.startswith(('(', '@', ',', '\t')):
            value -= 1.2
        elif token.startswith('='):
            value -= 2.1
        return value
    if word in {'parameter', 'parameters'}:
        return 3.8
    if word.startswith(('paramet', 'parammap')):
        return 3.6
    if word.endswith(('parameter', 'parameters', 'param', 'params')):
        return 2.8
    if word in {'args', 'kwargs', 'wargs', 'arguments'}:
        return 2.7 if name == 'Args' else 1.85
    if word in {'arg', 'argument'}:
        return 1.6 + 0.3 * capitalized
    if word in {'argv', 'argc', 'argparse'}:
        return 1.05
    if word in {'input', 'inputs'}:
        return 1.02 + 0.25 * capitalized
    if word in {'config', 'configs'}:
        return 0.62 + 0.08 * capitalized
    if word.startswith('particip'):
        return 1.4 if len(word) > 8 else 0.95
    if word == 'referred':
        return 0.82
    if word in {'reference', 'references'}:
        return 0.65 + 0.25 * capitalized
    if word in {'refer', 'ref', 'refs'}:
        return 0.43
    if word in {'num', 'nums'}:
        return 0.92
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = lexical_value(token)
    # A byte-level token may finish a character it cannot decode alone.
    if token.endswith('�') and len(prefix.token_ids) > 1:
        if prefix.document_ids[-1] != prefix.document_ids[-2]:
            return None, float(value)
        completed = prefix.text_prefixes[-1][-1:]
        if completed in {'参', '參'}:
            value = CHINESE[completed]
    return None, float(value)

programs.luna:
"""A token-level approximation for parameter and API-related vocabulary.

Parameter terms get the largest value; arguments, participants, inputs,
references, and configuration words get smaller values.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()
    letters = "".join(char for char in token if char.isalpha())

    if "param" in letters:
        return None, 4.5
    if "参数" in token:
        return None, 3.8
    if "参" in token or "參" in token:
        return None, 2.8
    if letters.startswith(("arg", "kwargs")):
        return None, 1.8
    if letters.startswith("particip"):
        return None, 1.5
    if letters.startswith("input"):
        return None, 1.0
    if letters.startswith("refer"):
        return None, 0.45
    if letters.startswith("config"):
        return None, 0.55
    return None, 0.0

"""Approximate a sparse signal for emphasis and degree words.

The clearest responses are to “really”; milder ones occur on focus and
intensifying adverbs such as “only”, “just”, “even”, and “very”.
"""
READS = ()

EMPHATIC_REALLY = {"really"}
OTHER_EMPHASIS = {
    "very", "so", "too", "quite", "rather", "pretty", "fairly",
    "extremely", "incredibly", "amazingly", "remarkably", "highly",
    "deeply", "strongly", "seriously", "truly", "absolutely",
    "completely", "totally", "entirely", "fully", "utterly",
    "especially", "particularly", "literally", "actually", "ridiculously",
    "genuinely", "definitely", "clearly", "simply", "just", "only",
    "even", "exactly", "merely", "barely", "hardly", "almost", "nearly",
    "slightly", "somewhat", "indeed", "surely",
}
CHINESE_EMPHASIS = {"非常", "简直", "极其", "特别", "真的", "真是", "完全"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in EMPHATIC_REALLY:
        return None, 9.5
    if word == "truly":
        return None, 4.0
    if word == "actually":
        return None, 1.8
    if word in OTHER_EMPHASIS or word == "able":
        return None, 0.85
    if any(word.startswith(part) for part in CHINESE_EMPHASIS):
        return None, 0.85
    return None, 0.0

programs.sol:
"""Approximate a language-sensitive spelling and tokenization feature.

Fading letter counts distinguish Persian-looking and Ukrainian-looking
contexts. Letter families, word boundaries, Persian function words and
inflection fragments set the response. Ukrainian і/ї/є are strongly
positive; word-initial з changes sign with the context. Dutch function
words and Scandinavian letters have smaller responses. Split characters
are scored differently before and after their UTF-8 decoding completes.
This captures the main contrasts, not most token-specific variation.
"""
READS = ()
PERSIAN = frozenset('پچژگکی')
UKRAINIAN = frozenset('іїєґІЇЄҐ')
VOWEL_LETTERS = frozenset('اآی')
PERSIAN_CONSONANT_SPELLINGS = frozenset('پچژگک')
ARABIC_LOAN_LETTERS = frozenset('ثحذصضطظعقغ')
PREPOSITIONS = frozenset(('به', 'با', 'در', 'بر'))
VERB_FRAGMENTS = frozenset(('ند', 'ده', 'ست', 'شد'))
DUTCH_CUES = frozenset(('een', 'ook', 'zijn', 'voor', 'niet', 'deze',
                        'zelf', 'aan', 'het', 'bij'))
DUTCH_POSITIVE = frozenset(('een', 'voor', 'bij', 'de', 'van', 'het',
                            'aan', 'meer'))
DUTCH_NEGATIVE = frozenset(('en', 'niet', 'als', 'op', 'kan', 'naar'))


def persian_letter(c):
    if c in VOWEL_LETTERS or c in 'زش':
        return 1.5
    if c in PERSIAN_CONSONANT_SPELLINGS:
        return 1.3
    if c in ARABIC_LOAN_LETTERS:
        return 0.25
    if c == 'ه':
        return 1.2
    if c in 'نسد':
        return 1.0
    if c in 'بج':
        return 0.5
    return 0.8


def arabic_fragment(word, letters, boundary, confidence):
    n = len(letters)
    native = sum(persian_letter(c) for c in letters) / n
    native += 0.2 * boundary - 0.1 * (n - 1)
    other = sum(-0.3 if c in 'اآدزشرهو' else 0.1 for c in letters) / n
    if boundary:
        if word in PREPOSITIONS or word == 'است':
            native, other = 1.9, -0.6
        elif word == 'و':
            native, other = 1.55, -0.35
        elif word == 'من':
            native, other = 0.35, 0.25
        elif word in ('ر', 'د'):
            native += 0.35
        elif word in ('م', 'ت'):
            native -= 0.2
    if word in VERB_FRAGMENTS or word == 'ان':
        native, other = 1.35, -0.45
    elif word == 'مان':
        native, other = 2.0, -0.6
    elif word == 'ها':
        native, other = 0.5, 0.25
    return confidence * native + (1.0 - confidence) * other


def split_character(prefix, s, p, u):
    last = prefix.text_prefixes[-1][-1]
    if last == '\ufffd':
        already_partial = (prefix.position > 0 and
                           prefix.text_prefixes[-2].endswith('\ufffd'))
        if not already_partial:
            if s == '\ufffd':
                return 2.4 * p
            if s == ' \ufffd':
                return 0.3 * p + 1.05 * u
    elif last.isdigit():
        return 0.7 * p
    elif last in 'Ій':
        return 1.0 * u
    elif last in 'їЇ':
        return 0.5 * u
    elif last == 'ظ':
        return 0.35 * p
    return 0.0


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        p = u = d = 0.0
    else:
        p, u, d = (0.95 * v for v in carry[1:])
    p += sum(c in PERSIAN for c in s)
    u += sum(c in UKRAINIAN for c in s)
    word, boundary = s.strip(), s.startswith(' ')
    if boundary and word in DUTCH_CUES:
        d += 1.0
    pc, uc, dc = min(1.0, p), min(1.0, u), min(1.0, 2.0 * d)
    letters = [c for c in word if '\u0600' <= c <= '\u06ff'
               and c.isalpha()]
    value = 0.0
    if letters:
        value = arabic_fragment(word, letters, boundary, pc)
    elif any('\u0400' <= c <= '\u052f' for c in s):
        if word.lower() == 'і':
            value = 1.2 if boundary else 1.4
        elif any(c in 'їЇєЄ' for c in s):
            value = 0.8
        elif s == ' з':
            value = -1.0 + 1.9 * uc
        elif word == 'ня':
            value = -0.5 + 0.4 * uc
        elif word == 'й':
            value = 0.1 + 0.9 * uc
        elif len(word) == 1 and not boundary:
            value = 0.5 * uc - 0.2 * (1.0 - uc) * (word in 'ншю')
    elif '\ufffd' in s:
        value = split_character(prefix, s, pc, uc)
    elif '\u200c' in s:
        value = 1.7 * pc
    elif '،' in s:
        value = 0.85 * pc
    elif any(c in 'øØæÆ' for c in s):
        value = 0.35 if any(c in 'øØ' for c in s) else 0.22
    elif s in (' og', ' sammen'):
        value = 0.25
    elif boundary and word in DUTCH_POSITIVE:
        value = 0.3 * dc
    elif boundary and word in ('ook', 'zelf', 'wel'):
        value = 0.55 * dc
    elif boundary and word in DUTCH_NEGATIVE:
        value = -0.13 * dc
    elif not any(c.isalpha() for c in s):
        value = (0.55 if s == ' ' else 0.2) * pc
    return (doc, p, u, d), float(value)

programs.luna:
"""Estimate a geometry vocabulary feature from the current token.

Square is the strongest cue, followed by named polygons and curves. The
program assigns weaker responses to geometry words and notation, and ignores
context, so it approximates rather than reproduces the component.
"""
READS = ()

SQUARES = {"square", "squares"}
POLYGONS = {"rectangle", "rectangles", "rectangular", "triangle", "triangles"}
CURVES = {
    "circle", "circles", "ellipse", "ellipses", "parabola", "parabolas",
    "parabolic",
}
SOLIDS = {
    "cubic", "cuboid", "cylinder", "cylinders", "cylindrical", "pyramid",
    "pyramids", "cone", "conical", "prism", "prisms", "wedge", "diamond",
    "rhombus", "polygon", "sphere", "spheres", "spherical",
}
SHAPE_WORDS = {"shape", "shapes", "shaped", "box", "boxes", "circumference"}
NOTATION = {"sqrt", "perpendicular", "arrow", "diameter"}
PARTS = {"squ", "tri", "rect", "cir", "ellip", "quad", "cub", "pyr"}
CJK_SHAPES = {
    "方", "形", "角", "圆", "圓", "球", "钻石", "正方", "三角", "立方",
}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].lower().strip(
        " \t\r\n.,;:!?()[]{}\"'"
    )
    if word in SQUARES:
        value = 6.4
    elif word in POLYGONS:
        value = 3.6
    elif word in CURVES:
        value = 2.5
    elif word == "cube" or word == "cubes":
        value = 2.4
    elif word in SOLIDS:
        value = 1.6
    elif word == "quadratic":
        value = 2.3
    elif word == "squared":
        value = 1.9
    elif word in NOTATION:
        value = 1.1 if word != "diameter" else 0.6
    elif word in {"triangular", "elliptical"}:
        value = 2.5
    elif word == "circular":
        value = 1.8
    elif word in {"round", "rounded"}:
        value = 0.6
    elif word == "grid":
        value = 0.4
    elif word in {"angle", "geometry", "geometric", "linear", "radius"}:
        value = 0.3
    elif word in SHAPE_WORDS:
        value = 1.0 if word.startswith("shape") else 0.8
    elif word in PARTS:
        value = 1.0 if word == "squ" else 0.5
    elif word in CJK_SHAPES:
        value = 0.7
    else:
        value = 0.0
    return None, value

programs.sol:
"""A token-local proxy for fused modal/predicate constructions.

Chinese tokens beginning with a recognized modal and a listed predicate
opener get large positive responses. Standalone modals, other auxiliary
constructions, and several Japanese verbal forms get smaller responses.
Selected traditional Chinese variants are normalized. Small secondary
rules cover English future adjectives and the end-of-turn marker.
Unmatched three/four-character Han tokens get a length-based baseline;
other unmatched tokens get zero. Previous context is not inspected, and
scattered token-specific effects are deliberately left unexplained.
"""
READS = ()

TRADITIONAL = str.maketrans(
    '會將夠應該讓於經為從對過來',
    '会将够应该让于经为从对过来',
)
# Verbs, prepositions, and adverbs that can begin a modal complement.
PREDICATES = tuple('''
做 去 用 在 把 比 看 好好 太 为空 不说 由 指 让 使 给 被 对 有 从 以 于
通过 根据 帮助 注意 加强 坚持 进一步 学会 考虑 知道
出现 导致 影响 造成 觉得 产生 选择 发生 引起 得到 满足
达到 迎来 成为 继续 持续 及时 联系 输入 存在 分为
进行 完成 获得 提供 发现 保持 提高 增加 完善 提升
创新 担心 超过 转载 说 吃 找 打 开 出 懂 受 买 达
'''.split())
MODALS = (
    ('可以', 4.35), ('能够', 4.1), ('需要', 4.0),
    ('应该', 1.5), ('应当', 1.5), ('可能', 3.35), ('希望', 3.9),
    ('要', 4.5), ('会', 3.8), ('能', 3.7), ('可', 3.8),
    ('将', 3.2), ('应', 4.1), ('想', 2.4), ('请', 2.5),
)


def response(token):
    s = token.strip().translate(TRADITIONAL)
    if s == '<|im_end|>':
        return 0.09
    if s in {'会', '要'}:
        return 0.75
    if s in {'可以', '能够', '应该', '应', '应当'}:
        return 0.55
    if s in {'能', '可能', '正在'}:
        return 0.3
    # These are lexicalized words, not productive modal + verb phrases.
    if s.startswith(('应用', '可爱', '可持续')):
        return 0.15
    if s == '应对':
        return 0.9
    for modal, strength in MODALS:
        if s.startswith(modal):
            tail = s[len(modal):]
            if tail in {'是', '会'} and modal not in {'要', '可'}:
                return 1.6
            if tail in {'有', '想'} and modal in {'要', '会'}:
                return 2.75
            if tail.startswith(PREDICATES):
                if modal == '可' and len(tail) == 1 and tail != '在':
                    return 1.8
                return strength
    if s in {'来看', '来自', '来自于'}:
        return 0.8
    # Other auxiliaries fused to the beginning of their predicate.
    for auxiliary, strength in (
        ('已经', 1.6), ('正在', 1.6), ('已', 2.0),
        ('不得', 2.8), ('不能', 2.8), ('不用', 2.5),
        ('不要', 2.5), ('不会', 2.6), ('不断', 1.4),
        ('来', 1.7), ('去', 1.3), ('被', 1.0), ('曾', 2.0),
        ('也', 0.9), ('就', 0.9), ('都', 0.8), ('是', 0.9),
    ):
        if s.startswith(auxiliary):
            tail = s[len(auxiliary):]
            if tail.startswith(PREDICATES) and tail != '说':
                return strength
    if s.startswith('不') and s[1:] in {'去', '在', '出', '懂', '受', '爱', '代表'}:
        return 1.0
    if s.startswith(('看不', '得不', '受不', '找不', '离不', '达不')):
        return 1.2  # Negative potential complements: 'cannot see/get/...'.
    if s in {'有助', '有助于', '越多', '就越', '越来越多'}:
        return 1.0
    if 'でき' in s:
        return 0.45 if s in {'でき', 'できません', 'できない'} else 1.05
    if ('られ' in s and s.endswith(('ない', 'ます'))) or s.endswith('やすい'):
        return 1.1
    if s in {'たい', 'したい', 'ぜひ'}:
        return 1.0
    if s.startswith(('を', 'が', 'に', 'も', 'は')):
        tail = s[1:]
        if tail.startswith(('出', '入', '行', '使', '持', '選', 'なる', 'なり',
                            'あり', 'ある', 'ない', '作', 'する', 'して', '受',
                            '必要', '利用', '使用')):
            return 0.4 if tail in {'ある', 'あります', 'なります'} else 0.8
    if s in {'には', 'にな', 'はこちら', 'してくれる', 'となる'}:
        return 0.35 if s == 'には' else 0.95
    if s in {'upcoming', 'forthcoming'}:
        return 0.8
    if len(s) in {3, 4} and all('\u4e00' <= c <= '\u9fff' for c in s):
        return 0.06 if len(s) == 3 else 0.23
    return 0.0


def step(carry, prefix, upstream):
    return None, float(response(prefix.token_strings[-1]))

programs.luna:
"""A sparse cue for longer Han-script tokens, Chinese modal characters, and
some inflected Japanese predicates; it does not infer sentence meaning.
"""

READS = ()

CHINESE_MODAL_CHARACTERS = frozenset("可会能要必须应需将愿不")
JAPANESE_PREDICATE_ENDINGS = (
    "ない", "なかった", "かった", "あった", "ある", "あります",
    "出る", "出た", "入る", "入った", "なる", "なった",
    "する", "して", "できる", "できない", "られない", "やすい",
)


def _han_count(text):
    return sum("\u3400" <= char <= "\u9fff" for char in text)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    han_count = _han_count(token)

    # Long Han-script tokens and Chinese modal-word spellings share the cue.
    if han_count >= 3:
        return None, 0.24
    if han_count and any(char in CHINESE_MODAL_CHARACTERS for char in token):
        return None, 0.24

    if token.endswith(JAPANESE_PREDICATE_ENDINGS):
        return None, 0.24
    return None, 0.0

programs.sol:
"""A local idiom detector, mainly for conventional source-code scaffolding.

Negative pulses mark familiar imports, headers, entry points, and boilerplate.
Positive pulses mark 'let me' and selected dependency/utility idioms. These
are several behaviors, not a single topic. The constants approximate training
activations; control tags get small offsets, and other text gets zero.
Only a short, document-local text suffix is kept; no token IDs or model
computations are used.
"""
import re

READS = ()

# Complete, recognizable expressions, their finishing token, and pulse size.
IDIOMS = (
    ('node_modules', '_modules', 0.88),
    ('site-packages', '-packages', 1.22),
    ('pkg_resources', '_resources', 1.0),
    ('eslint-plugin', '-plugin', 0.9),
    ('str_replace', '_replace', 0.43),
    ('json.dumps', '.dumps', 1.4),
    ('document.createElement', '.createElement', 0.7),
    ('console.log', '.log', -0.34),
    ('System.out', '.out', -0.52),
    ('System.in', '.in', -2.15),
    ('matplotlib.pyplot', '.pyplot', -1.2),
    ('pygame.time.Clock', '.Clock', -1.7),
    ('os.environ', '.environ', -0.67),
    ('using namespace std', 'std', -2.5),
    ('+++ b', 'b', -1.65),
    ('", line', 'line', -0.7),
    ('AUTO_INCREMENT', '_INCREMENT', -1.4),
    ('DEFAULT CHARSET', 'CHARSET', -1.5),
    ('CHARACTER_SET_RESULTS', '_RESULTS', -2.2),
    ('Bundle savedInstanceState', 'savedInstanceState', -2.2),
    ('super.viewDidLoad', '.viewDidLoad', -2.7),
    ('func viewDidLoad', 'viewDidLoad', -2.0),
    ('examiner should be directed', 'directed', -1.95),
    ('Apache License', 'License', -1.05),
    ('limitations under the License', 'License', -3.0),
    ('Tools | Templates', 'Templates', -4.3),
    ('OTHER DEALINGS IN THE SOFTWARE', 'SOFTWARE', -3.4),
    ('OTHER DEALINGS IN', 'IN', -1.8),
    ('TORT OR OTHERWISE, ARISING', 'ARISING', -2.0),
    ('FITNESS FOR A', 'A', -1.0),
    ('WARRANTIES OR CONDITIONS OF ANY', 'ANY', -1.4),
    ('WITHOUT WARRANTIES', 'WARRANTIES', -0.85),
    ('THE WARRANTIES', 'WARRANTIES', -0.5),
    ('Unless required', 'required', -1.0),
)
ENDINGS = {}
for phrase, ending, value in IDIOMS:
    ENDINGS.setdefault(ending, []).append((phrase, value))

C_HEADERS = {
    'stdio': -2.4, 'stdlib': -2.0, 'string': -1.5,
    'math': -1.1, 'time': -1.2, 'assert': -1.0,
    'unistd': -1.0, 'stdarg': -1.0, 'conio': -1.1,
}
SPRING_PACKAGES = {
    '.stereotype': -3.9, '.web': -1.25, '.data': -1.55,
    '.boot': -1.15, '.annotation': -1.4,
}
DOTNET_NAMESPACES = {
    '.Text': -2.1, '.Collections': -0.85, '.Generic': -1.4,
    '.Tasks': -3.2, '.Linq': -0.65,
}
HTTP_ANNOTATIONS = {
    '.RestController', '.RequestMapping', '.GetMapping', '.PostMapping',
    '.PutMapping', '.DeleteMapping',
}
ANDROID_UI_TYPES = {
    '.View', '.ViewGroup', '.TextView', '.RelativeLayout',
    '.RecyclerView', '.ArrayAdapter', '.Menu',
}
PYTHON_MODULES = {
    'typing', 'collections', 'datetime', 'threading', 'tkinter', 'pathlib',
}
CONTROL_MARKERS = {
    '<think>': -0.235, '</think>': 0.21,
    '<tool_response>': -0.12, '</tool_response>': -0.08,
    '<tool_call>': 0.08, '<|im_end|>': -0.055,
}


def activation(before, token):
    if token in CONTROL_MARKERS:
        return CONTROL_MARKERS[token]
    word = token.strip()
    if word.lower() == 'me' and re.search(r'\blet\s*$', before, re.I):
        return 0.47

    # Normalize source-line numbers, escaped newlines, and comment formatting.
    if word in ENDINGS:
        text = (before + token).replace('\\n', '\n')
        prose = re.sub(r'\b\d+\t', ' ', text)
        prose = re.sub(r'[\s*]+', ' ', prose).strip()
        for phrase, value in ENDINGS[word]:
            if prose.endswith(phrase):
                return value

    before = before.replace('\\n', '\n')
    if token == '.h' and re.search(r'#\s*include\s*[<"]', before):
        for name, value in C_HEADERS.items():
            if before.endswith(name):
                return value
    guard = (
        re.search(r'#ifndef\s+([A-Z_0-9]+)\s*$', before)
        if word == '#define' else None
    )
    if word == '#define' and guard:
        # Header-file guard names conventionally contain an H segment.
        return -2.9 if re.search(r'(^|_)H(_|$)', guard[1]) else -0.65
    if word == 'main' and re.search(r'\b(int|void|func)\s*$', before):
        return -0.95 if before.endswith(' void') else -0.55
    if word == 'main' and re.search(r'__name__\s*==\s*[\"\']__$', before):
        return -0.7
    if word in {"'__", '"__'} and re.search(r'__name__\s*==$', before):
        return -0.7
    if word == 'import' and re.search(
        r'\bfrom\s+(' + '|'.join(PYTHON_MODULES) + r')\s*$', before
    ):
        return -0.6

    match = (
        re.search(r'\b(?:import|using)\s+([\w.]*)$', before)
        if token.startswith('.') else None
    )
    if match:
        path = match.group(1)
        if path.startswith('org.springframework'):
            if path.endswith('.annotation') and token in HTTP_ANNOTATIONS:
                return -2.3
            if token in SPRING_PACKAGES:
                return SPRING_PACKAGES[token]
            if path.endswith('.stereotype') and token[1:2].isupper():
                return -2.8
        if path.startswith('System') and token in DOTNET_NAMESPACES:
            return DOTNET_NAMESPACES[token]
        if path.endswith('java.util') and token == '.List':
            # The List interface is stronger beside its ArrayList implementation.
            return -2.6 if 'java.util.ArrayList' in before else -0.95
        if path.startswith(('android', 'androidx')):
            if token == '.Bundle' and path.endswith('.os'):
                return -2.8
            if token in ANDROID_UI_TYPES:
                return -1.6
        if token[1:2].isupper():
            return -0.4

    if word == 'License' and re.search(r'\(the\s+[\\]?"$', before):
        return -2.2
    if word == 'esModule' and before.endswith('__') and 'defineProperty' in before:
        return -2.2
    if word == 'telephone' and 'attempts to reach the examiner by' in before:
        return -1.1
    if word == 'supervisor' and 'unsuccessful' in before and 'examiner' in before:
        return -1.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = activation(before, token)
    return (doc, (before + token)[-160:]), float(value)

