"""Returns a positive pulse on “me” immediately after “let”."""
READS = ()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    if tokens[-1].strip() == "me" and len(tokens) > 1:
        if tokens[-2].strip().lower() == "let":
            return None, 0.46
    return None, 0.0

programs.haiku:
"""Draft v5: identifiers that name a data field, property or parameter in code.

Activation is negative on words used as field, property or parameter names in code
(name, id, type, key, path, count, size, ...). It is strongest for `name` and `id` and
their compounds (username, _id, .name), weaker for other field names and for type
keywords (int, bool, true, false). It is switched off in ordinary prose (a word after
"the", "a", "this", "of"...), and is stronger the more code-like the preceding tokens are.
"""
READS = ()

NAME_WORDS = {"name", "username", "classname", "filename", "typename", "keyname", "getname"}
ID_WORDS = {"id", "pid", "uuid", "uid", "ids"}
FIELD_WORDS = {"type", "key", "path", "url", "count", "size", "width", "height", "version",
               "title", "description", "status", "email", "port", "length", "enabled", "num",
               "uri", "href", "timestamp", "kind", "mode", "datetime", "tostring", "loglevel"}
TYPE_WORDS = {"int", "bool", "boolean", "float", "integer", "true", "false", "double", "uint"}
PROSE_BEFORE = {"the", "a", "an", "this", "that", "his", "her", "their", "my", "your", "its",
                "of", "to", "in", "for", "and", "or", "with", "is", "was", "by", "on", "at",
                "from", "as", "be", "given", "first", "family", "real", "short", "large"}
CODE_CHARS = set('{}();=_."<>[]:\\')

def core(tok):
    return tok.strip().strip("._\"'(").lower()

def code_density(recent):
    hits = sum(1 for s in recent if any(ch in CODE_CHARS for ch in s))
    return hits / max(1, len(recent))

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    c = core(tok)
    if c in NAME_WORDS:
        v = -2.0
    elif c in ID_WORDS:
        v = -1.5
    elif c in FIELD_WORDS:
        v = -1.0
    elif c in TYPE_WORDS:
        v = -0.8
    else:
        return carry, 0.0
    if prev.strip().lower() in PROSE_BEFORE:
        return carry, 0.0
    v = v * (0.5 + 1.5 * code_density(prefix.token_strings[-17:-1]))
    return carry, float(v)

programs.luna:
"""Recognize language about promises, guarantees, and offers.

The component is usually quiet, but its strongest observed responses are
around making or keeping commitments: promises, assurances, warranties, and
compensation. This small lexical cue predicts a typical negative response;
it does not try to reconstruct the surrounding meaning.
"""
READS = ()

STRONG = (
    "promise", "commit", "guarantee", "承诺", "保证",
)
ASSURANCE = (
    "assur", "ensur", "warrant", "pledge", "undertak", "obligat",
    "compensat", "reimburse", "协议", "契约",
)
OFFER = (
    "offer", "promot", "advertis", "奖励", "促销",
)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if any(root in word for root in STRONG):
        return None, -0.98
    if any(root in word for root in ASSURANCE):
        return None, -0.595
    if any(root in word for root in OFFER):
        return None, -0.455

    # "vowed to" and "agrees to" can signal a commitment before its content.
    if word == "to" and len(prefix.token_strings) > 1:
        docs = prefix.document_ids
        if docs[-2] == docs[-1]:
            previous = prefix.token_strings[-2].strip().lower()
            if previous.endswith(("vow", "vowed", "agree", "agrees", "agreed")):
                return None, -0.56
    return None, 0.0

programs.sol:
"""Mostly a multilingual additive-particle feature ('also', 也, も, 도).

Predict a strong negative value on additions, smaller negatives on restriction
and contrast, and zero elsewhere. Treat fused phrases and idioms separately.
English phrase rules distinguish 'but also' and 'as well'.
This is a lexical approximation, not a claim that all these words are synonymous.
"""
READS = ()

# Translations of 'also', 'too', and 'likewise', grouped by response strength.
ALSO_WORDS = {
    'cũng': -4.1, 'também': -3.95, 'también': -3.25,
    'også': -2.85, 'också': -2.8, 'тоже': -2.8,
    'również': -2.35, 'juga': -2.2, 'ebenfalls': -2.1,
    'także': -2.0, 'även': -1.95, 'auch': -1.9, 'ook': -1.85,
    'też': -1.75, 'также': -1.7, 'aussi': -1.6, 'anche': -1.55,
    'également': -1.35, 'أيضا': -1.9, 'أيض': -1.7,
}
# Japanese additive, concessive and modal uses of the particle も.
MO_PHRASES = {
    'も': -4.4, 'にも': -4.3, 'ことも': -4.9, 'のも': -3.9,
    '人も': -3.75, '私も': -3.75, '方も': -4.05,
    'でも': -2.75, 'しても': -2.7, 'ても': -2.5, 'とも': -2.0,
    'としても': -2.9, 'なくても': -1.45, 'それでも': -1.35,
    'かも': -2.4, 'もある': -3.2, 'もあり': -3.25,
    'もあります': -2.6, 'もない': -2.6, 'もなく': -1.3,
    'もいい': -2.35, 'も多い': -1.8, 'も多く': -2.8,
    'こともあります': -3.25, 'こともある': -3.1,
}
DO_PHRASES = {
    '도': -2.95, '에도': -3.4, '라도': -2.65, '기도': -1.7,
    '지도': -1.6, '들도': -4.2, '에서도': -2.5,
}
COPULAS = {'is', 'are', 'was', 'were'}
PERSONAL_PRONOUNS = {'i', 'you', 'he', 'she', 'it', 'we', 'they'}


def chinese_also(word):
    """Separate addition from idioms meaning 'perhaps', 'that is', and 'never again'."""
    if '也许' in word or '也許' in word or word == '也就是说':
        return -0.85
    if word == '也就是':
        return -2.4
    if word.startswith('再也'):
