    elif lower == 'however':
        value = -0.63 if word == 'However' else -0.45
    elif lower == 'but':
        value = -0.345 if word == 'but' else -0.19
    elif lower == 'nor':
        value = -0.96 if word == 'Nor' else -0.4
    elif lower == 'too':
        value = -0.35
    elif lower == 'well':
        value = -0.55 if previous == 'as' else -0.13
    elif boundary and lower in ('только', 'nur', 'solo'):
        value = -0.54 if lower == 'только' else -0.35
    elif word in ('只', 'しか'):
        value = -0.8
    elif word in ('只能', 'だけ', '不过', 'しかし', 'さらに'):
        value = -0.45
    elif word == 'また':
        value = -0.64
    elif word.startswith(('还', '還')) and word != '还款':
        value = -0.8
    elif word == '又':
        value = -1.03
    elif word == '都':
        value = -1.2
    elif word.endswith('都') and word not in ('成都', '京都', '首都'):
        value = -1.3
    elif word.startswith('都'):
        value = -0.5 if word in ('都是', '都有', '都会', '都會') else -0.95
    elif word.startswith('但'):
