CONTRAST = {"but", "however", "although", "though", "yet", "whereas", "但"}
MOREOVER = {"additionally", "moreover", "furthermore", "並且", "并且"}
RESTRICTION = {"only", "both", "well", "только"}
PUNCTUATION = " \t\n\r,.;:!?()[]{}\"'“”‘’"


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].casefold().strip(PUNCTUATION)
    if word in ADDITIVE:
        return None, -3.5 if word == "also" else -2.8
    if word in CONTRAST:
        return None, -0.38 if word in {"but", "但"} else -0.6
    if word in MOREOVER:
        return None, -0.9 if word == "additionally" else -0.7
    if word in RESTRICTION:
