programs.sol:
"""Approximate a short-continuation response after an a-like ending.

Recognize a-like letters and open syllables across several writing systems.
An attached fragment then gets a negative value, decreasing with its length;
a fragment beginning or ending in another a-like unit is suppressed.
'a few' and 'a little', the spellings -idae/-inae, Arabic fathatan, and
Japanese vowel lengthening get separate strengths. Small background terms
cover 'few' and space-prefixed words after the article a. These rules capture
a dominant pattern, not the component's finer token-specific variation.
"""
import unicodedata
from functools import lru_cache

READS = ()
JAPANESE_A_VOWEL_KANA = frozenset(
    'アカサタナハマヤラワガザダバパヵァャヮ'
    'あかさたなはまやらわがざだばぱぁゃゎゕ'
)
A_HAN = frozenset('阿啊卡咖喀哈拉啦塔达達萨薩巴芭玛瑪马馬亚亞雅伽')

# Base strength per writing system; shorter fragments get a larger response.
STRENGTH = {
    'LATIN': 1.02, 'GREEK': 1.36, 'CYRILLIC': 1.12,
    'KATAKANA': 0.65, 'HIRAGANA': 0.17, 'ARABIC': 0.66,
    'HANGUL': 0.20, 'CJK': 0.05,
}

@lru_cache(maxsize=16384)
def a_ending(s):
    if not s:
        return False
    c = s[-1]
    base = unicodedata.normalize('NFD', c)[0].lower()
    if base in 'aαаяا' or c in JAPANESE_A_VOWEL_KANA or c in A_HAN:
        return True
    if '\uac00' <= c <= '\ud7a3':
        syllable = ord(c) - 0xac00
        return syllable % 28 == 0 and (syllable // 28) % 21 in (0, 2)
    return False

@lru_cache(maxsize=16384)
def continuation(s):
    if not s or s[0].isspace():
        return 0.0
    if s.isdecimal():
        return -0.57
    if s == 'ً':  # Arabic fathatan, often written after alef.
        return -2.11
    if a_ending(s):
        return 0.0
    if a_ending(s[0]) and len(s) > 1:
        return 0.0
    name = unicodedata.name(s[0], '')
    if s[0] == 'ー':
        return -1.10
    for script, strength in STRENGTH.items():
        if script in name:
            return -strength / len(s) ** 1.5
    if unicodedata.category(s[0]).startswith('P'):
        return -0.04
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    value = 0.0
    if token == ' few':
        value = -0.17
    if a_ending(previous):
        value = continuation(token)
        article = previous.strip()
        if article in ('a', 'A') and token in (' few', ' little'):
            value = -1.12 if token == ' few' else -1.50
            if article == 'A':
                value -= 0.21
        elif token == 'e' and previous.lower().endswith(('ida', 'ina')):
            # The Latin taxonomic endings -idae and -inae.
            value = -2.80 if previous.lower().endswith('ida') else -2.20
        elif token.startswith(' ') and article in ('a', 'A'):
            value = 0.04
    return (doc, token), float(value)

"""A spelling-local memory and record-keeping signal, rather than a topic detector.

Isolated 记/記 gives the largest response; longer words containing it are weaker.
Remembering, recording, registration, and their English relatives also respond,
as do the Japanese/Korean spellings 気 and 기. Small responses cover marking,
logging, and timing vocabulary. 'Memory of' and 'record of' continue onto 'of'.
These are recurring high-activation spellings in the training sample, not a
claim that every occurrence means remembering. State holds the preceding token
and resets at each document boundary.
"""
READS = ()

# Characters used in recollection, chronicles, storage, and counting.
RECOLLECTION_CHARACTERS = {
    '忘': 1.2,   # forget
    '忆': 0.9,   # recollection (simplified)
    '憶': 0.55,  # recollection (traditional/Japanese)
    '覚': 0.65,  # remember / become aware (Japanese)
    '紀': 1.5,   # chronicle
    '背': 0.8,   # recite; also 'back'
    '存': 0.6,   # store / retain
    '计': 1.25,  # count / calculate (simplified)
    '計': 0.9,   # count / calculate (traditional/Japanese)
}

# English word families. These tests also cover inflections and subword stems.
WORD_FAMILIES = (
    (('memor', 'memoir'), 0.65),
    (('registr',), 0.75),
    (('recall', 'denot'), 0.55),
    (('forget', 'forgot', 'unforget'), 0.75),
    (('journalist', 'chronic', 'cognit'), 0.5),
    (('reporter',), 0.75),
    (('logger',), 0.35),
)
COPY_AND_NOTATION = {
    'copy', 'noted', 'documented', 'transcription', 'remind', 'reminder',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lower().lstrip('_.-(/')
    value = 0.0

    if '�' in token:
        # Only a completed character is visible, never a future byte.
        completed = prefix.text_prefixes[-1][-1:]
        if completed in {'记', '記'}:
            value = 7.7 if completed == '记' else 4.3
    if token in {'记', '記'}:
        value = 7.6 if token == '记' else 6.8
        # Referencing above/below, forgetting, registration, or thinking of.
        if previous.endswith(('上', '下', '忘')):
            value = 5.2
        elif previous.endswith('登'):
            value = 4.7
        elif previous.endswith('惦'):
            value = 3.6
    elif any(c in token for c in '记記'):
        value = (2.3 if '记' in token else 1.9) / max(1, len(token) - 1)
        if token == '忘记':
            value = 1.2
        elif token == '书记':
            value = 1.3
    elif token in RECOLLECTION_CHARACTERS:
        value = RECOLLECTION_CHARACTERS[token]
    elif token in {'纪录', '紀錄'}:
        value = 1.7
    elif token in {'忘了', '注册', '기억', '気'}:
        value = {'忘了': 1.15, '注册': 0.85, '기억': 1.5, '気': 0.88}[token]
    elif token == '기':  # Korean syllable 'gi', also used in 기억 (memory)
        value = 2.2 if raw.startswith(' ') else 1.9
    elif word in {'memory', 'memories', 'mem', 'memo'}:
        value = {'memory': 1.75, 'memories': 1.45, 'mem': 0.4, 'memo': 0.4}[word]
    elif word.startswith('memorabl'):
        value = 1.2
    elif word.startswith('remember'):
        value = 0.65 if token[:1].isupper() else 0.9
    elif word.startswith('record'):
        value = 1.15
        if word in {'recorded', 'recording'}:
            value = 1.3
        elif word == 'recordings':
            value = 0.65
    elif word.startswith('register'):
        value = 1.25 if word.endswith('ed') else 0.9
    elif word.startswith('track'):
        value = 0.5 if word == 'track' else 0.35
    elif word.startswith('marker'):
        value = 0.65 if word == 'marker' else 0.85
    elif word in {'written', 'token', 'tokens', 'timer'}:
        value = {'written': 0.2, 'token': 0.25, 'tokens': 0.43, 'timer': 0.95}[word]
    elif word in COPY_AND_NOTATION:
        value = 0.35
    elif word == 'of':
        prior = previous.lower().lstrip('_.-(/')
        if prior in {'memory', 'memories'}:
            value = 0.95 if prior == 'memory' else 0.65
        elif prior.startswith('record'):
            value = 0.5
    else:
        for stems, weight in WORD_FAMILIES:
            if word.startswith(stems):
                value = weight
                break
    return (doc, token), value

"""A wood-centred lexical response, with spelling and material neighbours.

Predict a large positive contribution on wood, a smaller one on food,
and weaker ones on word, good and would.  Recognize inflections, wood
compounds and a few related material words/translations.  A small echo
continues onto 'of' or a split wood suffix.  Unlisted tokens get zero.
"""
READS = ()


def lexical(raw):
    word = raw.strip().lstrip('._-/').lower()
    if word == 'wood':
        return 6.0 if raw.startswith(' ') else 6.5
    if word == 'woods':
        return 3.8
    if word == 'wooden':
        return 2.7
    if word in ('woody', 'wooded', 'plywood'):
        return 1.7
    if word.startswith('wood') or (word.endswith('wood')
                                  and not word.endswith('ollywood')):
        return 2.5
    if word in ('food', 'foods'):
        return 3.5 if word == 'foods' or raw.strip()[:1].isupper() else 3.1
    if word == 'good':
        return 1.2
    if word in ('goods', 'goodness', 'hood', 'mood'):
        return 1.0
    if word in ('would', 'wouldn'):
        return 0.72 if word == 'would' else 0.36
    if word in ('word', 'words'):
        return 1.5 if word == 'word' else 1.7
    if word in ('ood', 'oods'):
        return 2.6 if word == 'ood' else 2.2
    if word in ('water', 'blood', 'wool', 'fuel', 'fuels'):
        return 0.82
    if word in ('timber', 'fruit', 'fruits', 'seed', 'seeds',
                'soil', 'meat', 'dough', 'seafood'):
        return 0.4
    # Wood/water/food in Chinese; wood in French; word stems in Russian.
    return {'木': 1.6, '水': 0.45, '食物': 2.85, '食品': 1.85,
            '食': 0.74, 'bois': 1.4, 'слов': 1.05, 'слова': 1.05}.get(word, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    base = lexical(raw)
    value = base
    if carry is not None and carry[0] == doc:
        previous, strength = carry[1:]
        if raw == ' of':
            value = 0.02 + 0.3 * strength
        elif previous.lower().endswith('wood'):
            value = {'en': 1.9, 's': 1.2, 'y': 1.5,
                     'work': 0.5}.get(raw, value)
    return (doc, raw, base), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:655: a lexical detector for "wood", "food", "good", "word", "would".

The component is silent on nearly every token. It fires on a small set of words, and
the strength depends on the word:

- wood family: "wood" (strongest, about 7), the "ood" spelling fragment (about 4.7),
  wooden and hardwood (about 2 to 2.5), and 木 (wood in Chinese).
- food: about 3 (and 食物).
- word family: word, words, about 1.5 to 1.7.
- good: about 1.2.
- would: about 0.7. Frequent, so it carries much of the mass.
- water, wool, blood: about 0.8. 水 (water) is weaker, about 0.4.
- the fragment "wo" (the start of would, word, wood): about 0.6.

The program reads only the newest token. It drops the leading space and lowercases
it, then looks the word up in the table. Any other token gives 0.
"""

READS = ()

# Mean activation on the word itself, measured on training text.
WOOD = {"wood": 7.0, "ood": 4.7, "wooden": 2.5, "hardwood": 2.0, "木": 1.8}
FOOD = {"food": 3.1, "食物": 2.9}
WORD = {"word": 1.5, "words": 1.7}
GOOD = {"good": 1.2}
WOULD = {"would": 0.72, "wo": 0.6}
MATERIAL = {"water": 0.8, "wool": 0.85, "blood": 0.82, "水": 0.4}

VALUE = {}
for group in (WOOD, FOOD, WORD, GOOD, WOULD, MATERIAL):
    VALUE.update(group)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    return carry, float(VALUE.get(word, 0.0))

programs.sol:
"""Detect smallness or low degree on the next token.

Small/low modifiers and micro-, sub-, min- prefixes prime a positive response.
It is stronger in familiar quantity phrases and compounds, and weaker for
punctuation, function words, or redundant size descriptions. A few especially
strong lexicalized compounds are explicit. Document boundaries reset the cue;
selected initial size cues have a negative response instead. The many small,
token-specific background activations are left at zero.
"""
READS = ()


def words(s):
    return frozenset(s.split())


SIZE = words('small smallest smaller little tiny minor')
LOW = words('low lowest lower less least lesser')
PREFIX = words('micro mini sub subs min minimum minimal')
YOUTH = words('child childhood young youngest youth junior early')
HAN = words('小 少 微 低 短 幼 子 减 少年 青年 的小')
CUES = SIZE | LOW | PREFIX | YOUTH | HAN | {'short', 'shortest'}
FUNCTION = words('a an the of in on at to for with and or is as than by from')
QUANTITY = words('number amount amounts quantity quantities length volume cost '
                 'rate rates level levels density pressure energy speed voltage')
SUB_COMPOUNDS = words('array arrays graph graphs field fields matrix match population '
              'ring nets system commands domain forum sp opt standard par mers')
YOUNG_PEOPLE = words('child children kid kids boy boys girl girls')
SIZE_TERMS = words('size bit fraction')


def strength(cue, raw, word):
    stem = word.lstrip('-_./')
    if not cue or not any(c.isalpha() for c in raw):
        return 0.0
    if cue == 'small' and stem in {'holder', 'holders'}:
        return 1.7
    if cue == 'minor' and stem in {'league', 'axis'}:
        return 1.2
    if cue == 'child' and stem in {'bearing', 'support'}:
        return 1.1
    if cue == '少' and stem in {'妇', '婦'}:
        return 1.1
    # microglia and miniatures: small biological or physical structures.
    if (cue == 'micro' and stem == 'gl') \
            or (cue == 'mini' and stem.startswith('atur')):
        return .88
    if cue == 'little' and stem in {'known', 'rock'}:
        return .75
    if cue == 'junior' and stem == 'high':
        return 1.0
    if raw[0:1].isspace() and word in FUNCTION:
        return -.15 if word == 'of' or (cue == 'lower' and word == 'than') else -.03
    if cue in SIZE and stem in YOUNG_PEOPLE | SIZE_TERMS:
        return -.12
    if cue in {'small', 'smallest', 'min', 'minimum', 'minimal'}:
        if stem in QUANTITY | {'business', 'businesses', 'positive', 'heap'}:
            return .45
    if cue in {'low', 'lowest'}:
        if stem in {'frequency', 'frequencies', 'power', 'heat', 'fat',
                    'maintenance', 'common', 'risk', 'key'}:
            return .6
        if stem in QUANTITY or (raw.startswith('-') and len(word) > 3):
            return .35
    if cue in {'less', 'lesser', 'least', 'lower'}:
        return .52 if stem in {'common', 'commonly', 'frequent', 'known'} else .03
    # Minification and minimum bounds/costs are literal reduction concepts.
    if cue in {'min', 'minimum', 'minimal'}:
        if stem.startswith('if') or stem in {'wage', 'wages', 'polynomial',
                                             'spanning', 'width', 'height', 'js', 'istic'}:
            return .65
        if stem.startswith('ister'):
            return -.25  # 'minister' is not a minimum construction.
    if cue in {'sub', 'subs'} and stem.startswith('stit'):
        return -.16      # likewise 'substitute', rather than a sub-part.
    if cue in {'sub', 'subs'} and stem in SUB_COMPOUNDS:
        return .5
    if cue in {'micro', 'mini'} and stem in {'array', 'vascular', 'fiber', 'fluid'}:
        return .45
    if cue in YOUTH:
        return .36 if stem in {'life', 'people', 'health', 'welfare', 'birth'} else 0.0
    if cue in {'short', 'shortest'}:
        return .25 if stem in {'term', 'period', 'range', 'path', 'story'} else .04
    return .08 if cue in SIZE else .14


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip('._(/\\').lower()
    first = carry is None or carry[0] != doc
    cue = '' if first else carry[1]
    value = strength(cue, raw, word)
    if first:
        if word in {'small', '小', '的小'}:
            value = -.78
        elif word in {'low', 'lowest', 'lower', 'mini'}:
            value = -.53
        elif word in PREFIX:
            value = -.4
    # Permit a separately tokenized hyphen inside a compound.
    next_cue = word if word in CUES else ''
    if cue and raw.strip() in {'-', '‐', '‑'}:
        next_cue = cue
    return (doc, next_cue), float(value)

programs.luna:
"""Track space-led paragraph breaks, with a stronger pulse after sentence stops.

A single space before a newline is positive, especially after ., !, or ?;
bare blank lines are slightly negative, as is a colon followed by three lines.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    last = carry[1] if carry is not None and carry[0] == doc else ""
    token = prefix.token_strings[-1]
    if (
        len(token) > 1
        and token[0] == " "
        and token[1] in "\r\n"
        and "\n" in token
        and all(c.isspace() for c in token)
    ):
        sentence_stop = last in (".", "!", "?")
        value = 1.7 if sentence_stop and token.count("\n") == 1 else (
            1.25 if sentence_stop else 1.0
        )
    elif token == "\n\n":
        value = -0.075
    elif token == ":\n\n\n":
        value = -0.4
    else:
        value = 0.0
    visible = [c for c in token if not c.isspace()]
    last = visible[-1] if visible else last
    return (doc, last), float(value)

programs.sol:
"""Short vowel pieces respond to the preceding letter, not just their own text.

Vowel-to-vowel boundaries are positive, consonant-to-vowel boundaries negative.
Latin biological endings -idae, -inae and -aceae get stronger predictions.
Digits joined to vowel-final text behave like weaker vowel continuations.
Uppercase and accented vowels use pooled estimates after consonants. Other
tokens stay near zero; NUL separators leave the previous-fragment state alone.
"""
import unicodedata

READS = ()
VOWELS = 'aeiouy'
# Previous vowel -> current a, e, i, o, u, y.
HIATUS = {
    'a': (0.46, 0.70, 0.35, 0.76, 0.38, 0.30),
    'e': (0.18, 0.21, 0.14, 0.21, 0.11, 0.10),
    'i': (0.24, 0.23, 0.22, 0.30, 0.16, 0.26),
    'o': (0.32, 0.35, 0.20, 0.42, 0.12, 0.16),
    'u': (0.24, 0.20, 0.10, 0.33, 0.26, 0.22),
    'y': (0.04, -0.01, 0.02, 0.02, 0.01, 0.04),
}
CONSONANT = (-0.064, -0.113, -0.107, -0.164, -0.027, -0.039)
CYRILLIC = str.maketrans('аеёиоуыэ', 'aeeiouye')


def plain(text):
    return ''.join(c for c in unicodedata.normalize(
        'NFD', text.lower().translate(CYRILLIC))
        if not unicodedata.combining(c))


def response(token, previous):
    s, p = plain(token), plain(previous)
    last = p[-1:]
    vv = bool(last) and last in VOWELS
    cv = bool(last) and last.isalpha() and not vv
    if len(token) == 1 and token in '0123456789':
        if vv:
            return (0.20, 0.08, 0.18, 0.12, 0.18, -0.01)[VOWELS.index(last)]
        if cv:
            if token == '0':
                return -0.08
            return -0.01 if token in '17' else -0.035
        if last.isdigit():
            return (0.0, -0.007, -0.003, 0.017, 0.007,
                    -0.007, -0.001, 0.006, -0.002, -0.013)[int(token)]
        return 0.002
    if len(s) == 1 and s in VOWELS:
        k = VOWELS.index(s)
        if vv:
            if token == 'e' and p.endswith('ida'):
                return 1.43
            if token == 'e' and p.endswith('ina'):
                return 0.92
            if previous[:1].isspace() and s == 'e' and last == 'a':
                return 0.52
            return HIATUS[last][k]
        if cv:
            if token.isascii():
                return CONSONANT[k] * (0.6 if token.isupper() else 1.0)
            return -0.04
        if last.isdigit():
            return (0.044, 0.064, 0.034, 0.12, 0.044, 0.055)[k]
        return (0.0, 0.02, 0.002, 0.01, 0.017, 0.026)[k]
    if len(s) == 2 and s[0] in VOWELS and s[1] == 's':
        k = VOWELS.index(s[0])
        if vv:
            return (0.60, 0.50, 0.15, 0.75, 0.25, 0.60)[k] * HIATUS[last][k]
        return (-0.017, -0.004, 0.025, -0.021, -0.01, 0.016)[k]
    if s in ('ae', 'ao', 'oe'):
        if s == 'ae' and p.endswith('ace'):
            return 0.72
        return {'ae': 0.17, 'ao': 0.15, 'oe': 0.09}[s] + (0.20 if vv else 0.0)
    if s == 's':
        return 0.08 if vv else 0.044 if cv else 0.012
    return 0.002


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
