"""Tokens after separators: fraction denominators, paths, and closing tags.

An initial slash (after a quote, whitespace, or an opening delimiter) makes a
stronger boundary than an internal path slash. Familiar root directories,
HTML tag names, and numerals strengthen the response. Spaces weaken it.
LaTeX's adjoining argument braces produce a smaller analogous signal.
"""
READS = ()

SYSTEM_DIRECTORIES = frozenset("usr bin sbin etc dev opt tmp var proc sys media mnt".split())
WORK_DIRECTORIES = frozenset("workspace test testbed home Users root".split())
HTML_TAGS = frozenset("""
a b i u p em strong div span body html head title section article
header footer main nav form input button label ul ol li table td th
pre code script style summary details select option sub sup h1 h2 h3 h4
""".split())
TABLE_ROWS = frozenset(("tr", "tbody", "thead", "tfoot"))


def boundary_value(token, previous):
    if not token or token.startswith(("/", "<|")):
        return 0.0
    if token.isspace():
        return 1.05 if len(token) == 1 else 0.45
    if token.lstrip().startswith("("):
        return 1.7
    if token[0].isspace():
        return 0.65
    if not token[0].isalnum() and token[0] != "_":
        return 0.8
    if token.isascii() and token.isdigit():
        return 2.2
    if token in SYSTEM_DIRECTORIES:
        return 3.5
    if token in ("Applications", "Volumes"):
        return 4.2
    if token in WORK_DIRECTORIES:
        return 3.05
    if previous.endswith("</"):
        if token in TABLE_ROWS:
            return 3.2
        if token in HTML_TAGS:
            return 2.25
    if token.isascii() and len(token) == 1 and token.isalpha():
        return 2.0
    if token.startswith("_"):
        return 2.0
    # Beginning an absolute path, rather than continuing a path segment.
    before = previous[:-1]
    if before and (before[-1].isspace() or before[-1] in "\"'`=:[(>"):
        return 2.3
    return 1.05


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    prev, spaced = (carry[1:] if carry is not None and carry[0] == doc
                    else ("", False))
    slash = prev.endswith(("/", "／")) and not prev.endswith("//")
    trimmed = prev.rstrip()
    spaced_slash = trimmed.endswith(("/", "／")) and not trimmed.endswith("//")
    value = 0.0
    if slash:
        value = boundary_value(token, prev)
        if prev.endswith("*/"):
            value *= 0.1
        elif prev.endswith("./"):
            value *= 0.57 if token in WORK_DIRECTORIES else 0.8
        elif prev.endswith("></"):
            value *= 0.55
    elif (spaced or spaced_slash) and token.isdigit():
        value = 1.0
    elif prev.endswith("}{"):
        value = 0.85
    elif prev in ("\\", "\\\\"):
        value = 0.1 if len(prev) == 1 else 0.23
    elif "/" in prev and len(prev.rsplit("/", 1)[1]) == 1:
        value = 0.15
    return (doc, token, token.isspace() and (slash or spaced)), float(value)

