    ({'cal', 'rm', 'bf', 'it', 'sf', 'tt', 'mathrm', 'mathsf', 'mathtt',
      'mathit', 'mathcal', 'mathbb',
      'mathfrak', 'mathbf', 'boldsymbol', 'bm', 'textrm', 'textbf'},
     3.5, 'font'),
    ({'hat', 'widehat', 'tilde', 'widetilde', 'bar', 'overline',
      'underline', 'vec', 'dot', 'ddot'}, 3.7, 'accent'),
    ({'overrightarrow', 'overleftarrow', 'overleftrightarrow'}, 4.3, 'accent'),
    ({'frac', 'dfrac', 'tfrac', 'binom'}, 2.15, 'fraction'),
    ({'sqrt'}, 1.75, 'root'),
    ({'begin'}, 1.9, 'environment'),
    ({'end'}, 2.9, 'environment'),
    ({'label', 'ref', 'eqref', 'cite', 'citep', 'caption'}, 1.1, 'reference'),
    ({'text', 'texttt', 'textsc'}, 2.6, 'text'),
    ({'mbox', 'fbox', 'boxed', 'operatorname', 'hspace', 'vspace',
      'newcommand', 'renewcommand', 'overset', 'underset'}, 2.2, 'group'),
