            role = 'group'
            if left.endswith(('^', '_')):
                value, role = (3.25 if left.endswith('^') else 3.5), 'script'
                if left.startswith('}'):
                    value = 1.6 if tail.endswith('\\') else 3.0
            elif left.endswith('$'):
