                    value = 1.8
                if right.startswith('\\'):
                    value = max(0.4, value - 0.6)
                elif right == '{':
                    value, role = min(value, 3.8), 'group'
                elif right and role != 'script':
                    value = min(value, 1.8)
            elif left.endswith(('(', ',')):
                value = 0.3
            if '}' in right:
                value = 0.0
        if not s.endswith('{') or value < 0.25:
            role = ''
