"""LaTeX brace openers. The component fires on the "{" that opens a LaTeX argument, most
strongly when the brace follows a superscript or subscript marker (x^{, x_{), less after an
ordinary command (\\frac{, \\text{), and only weakly in math written with $...$. Braces that
open code blocks (" {", "{" then a newline or quote) and ordinary text stay near zero.
Table pipes get a small value, and a backslash typed right after an opening brace gets a
moderate one."""
import re

READS = ()

STYLE_CMDS = {"hat", "vec", "mathrm", "mathbf", "bb", "bf", "cal", "text", "mathcal", "boldsymbol"}
REF_CMDS = {"label", "ref", "cite", "eqref", "begin", "ce"}
CMD = re.compile(r"\\([A-Za-z]+)[^\s\\]{0,3}$")
DOLLAR_MATH = re.compile(r"\$[^$\n]*$")


