    tok = prefix.token_strings[-1]
    before = prefix.text_prefixes[-2][-80:] if len(prefix.token_strings) > 1 else ""
    if tok == "}{":
        return carry, 1.4                      # second argument, as in \frac{a}{b}
    if "{" in tok:
        if tok.endswith(("\n", "\r", '"')) or (tok.startswith(" ") and tok != " {\\"):
            return carry, 0.0                  # code block braces: " {", "{\n", ' {"'
        if before.endswith(("^", "_")):
            return carry, 5.5                  # bare brace right after ^ or _
        if "^{" in tok or "_{" in tok:
            return carry, 3.3                  # brace token that opens a script
        m = CMD.search(before)
        if m:
            name = m.group(1)
            if name in STYLE_CMDS:
                return carry, 3.2
            if name in REF_CMDS:
                return carry, 1.2
            return carry, 2.2                  # other LaTeX command argument
        if DOLLAR_MATH.search(before):
            return carry, 1.1                  # brace inside $...$ math
        return carry, 0.3                      # other bare brace
    if tok in (" |", "|"):
        return carry, 0.15
    if tok == "\\" and before.endswith("{"):
        return carry, 1.3                      # a command typed right after an opening brace
    return carry, 0.0

