    elif word in MEDIUM:
        value = -1.2
    elif word in MILD:
        value = -0.6
    elif word in PIECE:
        value = PIECE[word]
    elif word == "of" and prev in STRONG:
        value = -2.1
    elif word == "of" and prev in MEDIUM:
        value = -1.0
    elif word == "of" and prev == "piece":
        value = 0.85
    else:
        value = 0.0
    return carry, float(value)

"""Adjective stems ending in "-al" (normal, total, final, moral, royal, ...).

The component goes strongly negative on the token that completes such a stem, which is
where the model could next write a suffix like -ity, -ize or -ism (normality, royalty,
normalize). Its write direction, taken with negative activation, raises the logits of
exactly those suffixes (-ized, -izing, -ities, -ty, -istic). So the program predicts:
  - a token ending in "al" (word-initial, like " normal", or mid-word, like "ital")
    gets a negative value, larger for mid-word fragments than for whole words;
  - a token ending in other "l" gets a small negative value;
  - everything else is 0.
"""

READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    s = raw.strip().lower()
    if s.endswith("al"):
        return carry, (-1.4 if raw.startswith(" ") else -2.0)
    if s.endswith("l"):
        return carry, -0.2
    return carry, 0.0

programs.sol:
"""Local negation and split-word cues, using fitted response sizes.

This partial approximation responds negatively to English certainty/ability
words (especially after negation), Arabic word starts and vowel marks, and test
assertions. Some prefixed word continuations respond positively. Chinese
negation uses a separate character/adjective rule. Other positions predict zero;
this does not model sentence meaning or the many smaller lexical responses.
"""
import re
import unicodedata

READS = ()
NEGATION = {'not', "'t", '’t', 'hardly'}
DEGREE = {'so', 'quite', 'really', 'very', 'pretty', 'exactly', 'even'}
ARTICLES = {'a', 'an', 'the'}
BE = {'be', 'being', 'been', 'is', 'are', 'was', 'were', 'am'}
LATIN_PREFIXES = {'re', 'pre', 'un', 'trans', 'irre'}
OPERATION_FRAGMENTS = {
    'compile', 'compiled', 'eval', 'format', 'entry', 'loading',
    'processing', 'process', 'compute', 'program', 'programming', 'config',
    'construct', 'trace', 'working', 'frame', 'structure', 'assignment',
}
# Arabic clitics/article followed by conjugation or derivation prefixes.
ARABIC_PREFIX = re.compile(
    r'^[وف]?(?:ب|ل)?(?:ال)?(?:ت|ي|ن|أ|إ|م|مت|مست|است|أت|مؤ)$'
)
ARABIC_STARTS = {
    'ت': -0.65, 'أ': -0.44, 'ن': -0.25, 'الت': -0.25,
    'ي': -0.14, 'م': -0.14, 'الإ': -0.14, 'أن': -0.31,
}
VOWEL_MARKS = {
    'ُ': -1.65, 'َ': -0.12, 'ِ': -0.12,
    'ً': -0.12, 'ّ': -0.12, 'ْ': -0.25,
}


def arabic(s):
    return bool(s) and all(
        '\u0600' <= c <= '\u06ff' and unicodedata.category(c).startswith('L')
        for c in s
    )


def arabic_response(token, previous, older):
    word, prev = token.strip(), previous.strip()
    if token == 'ُ' and prev == 'و':
        return -0.70
    if token == 'ّ' and previous == 'ُ':
        return -1.0
    if token in VOWEL_MARKS:
        return VOWEL_MARKS[token]
    if token[:1].isspace() and arabic(word):
        value = ARABIC_STARTS.get(word, 0.0)
        if word not in ARABIC_STARTS and len(word) <= 3 and word.startswith('ت'):
            value = -0.33
        if prev in {'لا', 'لم', 'لن', 'ولا', 'أن', 'كنت'}:
            if word.startswith(('ت', 'أ', 'ن')):
                value -= 0.62
            elif word == 'ي':
                value -= 0.15
        return value
    boundary = previous[:1].isspace() or not arabic(older[-1:])
    if arabic(token) and ARABIC_PREFIX.fullmatch(prev):
        if boundary or prev.startswith('ال'):
            value = (0.50 if len(token) > 1 else 0.20) + 0.20 * prev.endswith('ت')
            if token.startswith(('ا', 'ت', 'ى', 'ی', 'ک', 'گ')):
                value = 0.03
            return -0.65 if token == 'ؤ' else value
    return 0.0


def english_response(word, previous, older):
    prev, old = previous.strip().lower(), older.strip().lower()
    value = 0.0
    if word == 'sure':
        value = 0.025 if prev in {'make', 'makes', 'making'} else -0.14
        if prev in {'am', "'m", '’m'}:
            value = -0.23
        if prev in DEGREE:
            value = -0.53
    elif word == 'able':
        value = -0.26 if prev in {'be', 'being', 'been'} else -0.13
    elif word in {'necessarily', 'matter', 'worry', 'really', 'good'}:
        value = -0.12
    if prev in NEGATION:
        value = -0.07
        if word == 'sure':
            value = -0.99 if previous == ' not' else -0.81
        elif word in {'necessarily', 'able', 'worry', 'meant', 'good'}:
            value = -0.75
        elif word in {'matter', 'that'}:
            value = -0.56
        elif word in ARTICLES:
            value = -0.36
        elif word in {'just', 'merely', 'currently'}:
            value = 0.34
        elif word in {'be', 'been', 'have', 'only', 'even'}:
            value = 0.03
    elif old in NEGATION and prev in DEGREE | BE | ARTICLES:
        if word in {'sure', 'able', 'good'}:
            value -= 0.27
    elif prev == 'never':
        value = 0.84 if word in {'before', 'again'} else 0.10
        if word in {'be', 'been', 'was', 'ever'}:
            value = 0.38
        elif word in {'sure', 'able', 'good'}:
            value = -0.48
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, older = '', ''
    else:
        previous, older = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = previous.strip().lower()
    value = arabic_response(token, previous, older)
    if token.startswith(' ') and word.isascii() and word.isalpha():
        value = english_response(word, previous, older)
    elif token.isascii() and token.isalpha():
        if prev.lstrip('_/') in LATIN_PREFIXES:
            strong = word in OPERATION_FRAGMENTS | {'vers', 'specified'}
            value = 0.48 if strong else 0.08
    if prev == 'never' and token == '-before':
        value = 1.24
    if token.startswith('.assert'):
        value = -0.64 if token == '.assertIsInstance' else -0.18
    elif prev == 'def' and word in {'test', 'setup', 'teardown'}:
        value = -0.42
    elif word == '/tests':
        value = 0.18
    elif word == '/unit':
        value = -0.31
    chinese = bool(token) and all('\u4e00' <= c <= '\u9fff' for c in token)
    if prev in {'不', '未'} and chinese:
        value = 0.22 if len(token) == 1 else 0.0
        if word in {'难', '難', '够', '夠', '好的', '好', '成熟', '确定', '必要'}:
            value = -0.60
    return (doc, token, previous), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 672 (v1): a negation detector.

Plain-language summary: this component goes negative on the word that completes a
negated phrase ("not sure", "not necessarily", "not able", "don't worry", "doesn't
matter"), and goes negative on the Arabic negation-plus-verb stem " ت" (after لا/لم/لن).
It goes weakly positive on Arabic word fragments that have no leading space (the
middle or end of a longer Arabic word). Everything else is predicted as 0.
"""
import unicodedata

READS = ()

NEGATORS = {" not", " Not", "not", "Not", "'t", "’t", " never", "لا", "لم", "لن"}
NEGATED_PREDICATES = {" sure", " necessarily", " able", " worry", " matter"}
ARABIC_NEGATORS = {"لا", "لم", "لن"}


def _is_arabic_fragment(s):
    letters = [c for c in s if c.isalpha()]
    return bool(letters) and all("ARABIC" in unicodedata.name(c, "") for c in letters)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if len(prefix) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        previous = ""
    else:
        previous = prefix.token_strings[-2]
    if previous in NEGATORS and token in NEGATED_PREDICATES:
        return carry, -0.85
    if token == " ت" and previous in ARABIC_NEGATORS:
        return carry, -1.0
    if token == " ت":
        return carry, -0.55
    if _is_arabic_fragment(token) and not token.startswith(" "):
        return carry, 0.07
    return carry, 0.0

programs.sol:
"""Approximate strong @@ responses and smaller document/software-word cues.

Unified-diff hunk markers respond more than inline doubled at signs, and
first hunks after +++ file headers respond most. Tokens ending the line
have a smaller response. Resource-related words add spelling-specific
positive responses; other tokens get zero. These are literal token cues,
not a general semantic classifier. The program omits the component's many
smaller, less coherent lexical responses.

State keeps bounded line prefixes and resets at document boundaries.
"""
READS = ()

FORMATS = {'pdf', 'epub'}
PUBLICATIONS = {'books', 'magazine', 'magazines', 'publication', 'printed'}
VERSIONS = {'version', 'versions', 'release', 'released'}
DIFFERENCES = {'diff', 'difference', 'differences'}


def token_response(token):
    word = token.strip()
    lower = word.lower()
    if '@' in token:
        return 0.075
    if lower in FORMATS:
        return 0.43 if word == 'PDF' else 0.30
    if lower in {'library', 'libraries'}:
        return 0.27 if word == 'Library' else 0.08
    if lower in {'download', 'downloads'}:
        return 0.21 if word == 'Download' else 0.09
    if lower == 'tools':
        return 0.20 if token.startswith(' ') and word.islower() else 0.04
    if lower in PUBLICATIONS:
        return 0.15
    if lower in VERSIONS:
        return 0.22 if lower == 'released' else 0.08
    if lower in DIFFERENCES:
        return 0.20 if lower == 'diff' else 0.09
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, previous = '', ''
    else:
        _, line, previous = carry
    token = prefix.token_strings[-1]
    value = token_response(token)
    if '@@' in token:
        if '\n' in token:
            value = 0.42
        elif not line.strip():
            value = 0.76 if previous.startswith('+++') else 0.66
        elif line.lstrip().startswith('@@ -'):
            value = 0.70 if previous.startswith('+++') else 0.66
        else:
            value = 0.46
    parts = (line + token).split('\n')
    if len(parts) > 1:
        previous = parts[-2][:120]
    line = parts[-1][:120]
    return (doc, line, previous), value

programs.luna:
"""Predict negative responses to French auxiliaries and French-looking word endings.

The word list handles common forms directly; ending rules need nearby French function
words, which helps avoid ordinary English words with similar spelling.
"""

READS = ()

FRENCH_CUES = frozenset({
    "le", "la", "les", "un", "une", "des", "du", "de", "et", "au",
    "aux", "qui", "que", "qu", "pas", "dans", "pour", "par", "avec",
    "sur", "ce", "cette", "ces", "il", "elle", "ils", "elles", "nous",
    "vous", "leur", "mais", "comme", "l", "n", "être", "était", "été",
})

FRENCH_VERBS = frozenset({
    "est", "sont", "ont", "fut", "font", "fait", "a", "avait", "avaient",
    "sera", "seront", "doit", "doivent", "peut", "peuvent", "vient", "dit",
})
FRENCH_CONTRACTIONS = frozenset({
    "n'est", "n’est", "c'est", "c’est", "l'est", "l’est", "n'a", "n’a",
    "n'ai", "n’ai", "j'ai", "j’ai", "l'a", "l’a", "s'est", "s’est",
})

STRONG_ENDINGS = ("aient", "issez", "issent", "urent", "ent", "ait", "ant",
                  "ez", "ont")
OTHER_ENDINGS = ("er", "ir", "re", "oir", "ée", "ées", "és", "é")


def step(carry, prefix, upstream):
    """Keep the current word and recent words, resetting both at document boundaries."""
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word, history = "", ()
    else:
        _, word, history = carry

    for char in prefix.token_strings[-1].lower():
        if char.isalpha():
            word += char
        elif char in "'’" and word:
            word += char
        else:
            if word:
                history = (history + (word,))[-12:]
            word = ""

    recent_french = sum(item in FRENCH_CUES for item in history[-8:])
    current = word.strip("'’")
    if current in FRENCH_CONTRACTIONS:
        value = -0.5
    elif current in FRENCH_VERBS and (current != "a" or recent_french):
        value = -0.22
    elif current.endswith(STRONG_ENDINGS) and len(current) >= 4 and recent_french:
        value = -0.55
    elif current.endswith(OTHER_ENDINGS) and len(current) >= 4 and recent_french >= 2:
        value = -0.4
    else:
        value = 0.0
    return (doc, word, history), value

programs.sol:
"""Sparse lexical peaks, not a single semantic category.

Selected ser/shi/si/se spellings and 世 (world/generation) forms are positive.
Continuance, repetition, interruption characters, selected Chinese intensifying
negations, and enumeration are negative. Fixed strengths approximate lexical
peaks; other tokens and context-dependent responses are omitted.
"""
READS = ()

SIBILANT_SPELLINGS = {
    '시': 2.65, '세': 2.5, 'シ': 1.65, '仕': 1.6, '西': 1.3,
    'せ': 1.0, '示': 1.0, 'セ': 0.8, '希': 0.8,
    '視': 0.5, '视': 0.5, '士': 0.4, '丝': 0.4, 'し': 0.25,
    'σ': 0.36, 'ش': 0.35, 'ษ': 0.45,
    '世': 3.4, '一世': 2.1, '世家': 1.0,
}
CONTINUITY = {
    'constantly': -1.45, 'continually': -1.4, 'continuously': -0.7,
    'endless': -1.35, 'endlessly': -1.25, 'tirelessly': -2.3,
    'repeatedly': -0.85, 'relentlessly': -1.1, 'throughout': -0.34,
    'unlimited': -0.75, 'countless': -0.85, 'increasingly': -0.5,
    'どんどん': -1.65, 'まだまだ': -1.2, '何度も': -1.15,
    '日々': -1.2,
}
# Recurrence, interruption, and negations like 'not merely' or 'countless'.
INTENSIFIERS = (
    (-3.1, '不间断 不間斷 不懈 不乏'.split()),
    (-2.3, '断 斷 不止'.split()),
    (-2.1, '不仅 不僅 不禁'.split()),
    (-1.7, '不但 不惜 充满 充滿'.split()),
    (-1.05, '不少 无数 無數 无限 無限 不舍 不捨 无疑 無疑'.split()),
    (-1.0, '纷纷 紛紛 遍 屡 屢 逐渐 逐步 反复'.split()),
    (-0.65, '不过 不過 不再 越来越 有不少 一遍 中断'.split()),
    (-0.21, ('不',)),
)


def response(token):
    word = token.strip(' \t\n_-./')
    lower = word.lower()
    if lower in ('ser', 'сер'):
        return 0.7 if token == 'ser' else 1.0
    if lower.startswith(('serial', 'deserial')):
        return 0.5
    if lower == 'sigma':
        return 0.36
    if lower in ('enum', 'enums', 'enumerate', 'enumeration'):
        return -0.7
    if word in ('시', '세') and token.startswith(' '):
        return 2.5 if word == '시' else 1.9
    if word in SIBILANT_SPELLINGS:
        return SIBILANT_SPELLINGS[word]
    if lower in CONTINUITY:
        return CONTINUITY[lower]
    if word.startswith(('不断', '不斷')):
        if len(word) == 2:
            return -7.0 if word == '不断' else -5.9
        return -5.3 if len(word) == 3 else -3.1
    if word.startswith('不停'):
        return -3.9 if len(word) == 2 else -3.55
    for strength, spellings in INTENSIFIERS:
        if word in spellings:
            return strength
    return 0.0


def step(carry, prefix, upstream):
    return None, float(response(prefix.token_strings[-1]))

programs.haiku:
"""layers.0.mlp.down_proj:676, a word-list explanation.

The component's activation is set almost entirely by the current token. It is strongly
negative on words for continual or countless occurrence: Chinese 不断 ("continuously")
and its relatives, 不停, 不乏, 无数 ("countless"), 充满 ("full of"), and English
"constantly", "continually", "continuously", "endless", "repeatedly", "countless".
It is positive on the Chinese character 世 ("world"), on Korean 시 and 세, on the Japanese
kana シ, せ, セ, on the characters 西, 仕, 示, and on the spelling "ser" (Ser, SER, сер).
Every other token gets 0. Each listed word gets a fixed value, graded by its typical size.
"""

READS = ()

# Negative: continual or countless occurrence.
NEG_STRONG = {"不断", "不斷", "不断地", "不断的", "不停", "不间断", "不乏"}
NEG_MEDIUM = {
    "断", "斷", "中断", "不仅", "不僅", "不但", "不禁", "充满", "充滿", "无数",
    "constantly", "continually", "continuously", "endless", "countless", "repeatedly",
    "increasingly", "abound", "unlimited", "屡", "纷纷", "频频", "遍", "一遍", "日々", "どんどん",
}
NEG_WEAK = {"不少", "不错", "枚", "慢慢", "throughout", "种种", "接连"}

# Positive: the character 世 and sibilant-like syllables and the spelling "ser".
POS_STRONG = {"世", "시", "세"}
POS_MEDIUM = {"西", "仕", "示", "シ", "せ", "セ", "ser", "сер", "_ser"}
POS_WEAK = {"士", "视", "視", "丝", "σ", "sigma", "ش", "س"}

LEVELS = (
    (-4.0, NEG_STRONG), (-1.5, NEG_MEDIUM), (-0.7, NEG_WEAK),
    (3.0, POS_STRONG), (1.2, POS_MEDIUM), (0.4, POS_WEAK),
)


def step(carry, prefix, upstream):
    """The activation at this position: the value of the current token's word, or 0."""
    word = prefix.token_strings[-1].strip().lower()
    for value, words in LEVELS:
        if word in words:
            return None, value
    return None, 0.0

programs.sol:
"""A partial detector of structured-text joins and encoding notation.

Positive responses mark HTML numeric entities, escaped bytes, adjoining
expressions, reference hashes, and qualified names. Special contexts include
UTF-8/COVID-19 hyphens, SQL string lengths and standard-library scopes.
A few familiar identifier names also respond. Ordinary text stays near zero;
this deliberately omits most of the component's smaller lexical variations.
Recent text and a flag for Python syntax distinguish hashes used as comments.
Both reset at document boundaries.
"""
import re

READS = ()

# Recognizable standardized identifiers, not vocabulary token ids.
IDENTIFIERS = {
    'utf': 0.77,       # Unicode encoding
    'uuid': 0.54,      # Universally unique identifier
    'isbn': 0.71,      # Book identifier
    'ipv': 1.67,       # Internet protocol version prefix
    'charset': 0.58,   # Character-set declaration
}

# Delimiters linking successive arguments or expressions within one token.
JOINS = (
    ('](', 0.55),       # Markdown link destination
    (')/(', 0.46),      # Division of parenthesized expressions
    (')=(', 0.29),      # Equality of parenthesized expressions
    ('}_{', 0.51),      # Braced subscript
    ('},{', 0.67),      # Consecutive objects
    ('],[', 0.66),      # Consecutive arrays
    (']{', 0.58),       # Bracket-to-brace transition
    ('){', 0.17),       # Argument list followed by a body
    ('}(', 0.25),       # Braced expression followed by arguments
    ('><', 0.29),       # Adjacent markup tags
)


def activation(s, recent, first, python):
    t = s.strip()
    match = re.search(r'([A-Za-z_][A-Za-z_0-9]*)$', recent)
    word = match[1].lower() if match else ''
    if '&#' in t:
        return 1.17
    if t.startswith('\\x') and len(t) <= 3:
        if t == '\\x':
            return 0.27
        if t[-1] in 'ab':    # Continuation-byte prefixes
            return 0.78
        if t[-1] in 'cd':    # Two-byte UTF-8 lead-byte prefixes
            return 1.33
        if t[-1] in 'ef':    # Longer UTF-8 lead-byte prefixes
            return 0.98
    if t == '\\u':
        return 0.54
    if t == '-':
        if word == 'utf':
            return 1.93
        if word == 'covid':
            return 0.79 if recent.endswith(' COVID') else 1.25
        if word in {'aes', 'license'}:
            return 0.88
        return 0.01
    if t == '(' and word in {'varchar', 'nvarchar'}:
        return 1.10 if re.search(r' n?varchar$', recent, re.I) else 0.08
    if t == '(' and word in {'rgb', 'rgba'}:
        return 0.30
    if t == '-type' and word == 'ref':
        return 0.48
    if t.startswith('::'):
        return 0.74 if word == 'std' else 0.53 if recent.endswith('.py') else 0.34
    if t.count('#') == 1:
        if t != '#':
            return 0.40
        if first:
            return -0.07
        if recent.endswith('](') or re.search(r'\.(md|html?)$', recent):
            return 1.01
        if recent.rstrip().endswith('{'):
            return 0.74
        if not recent.rsplit('\n', 1)[-1].strip():
            code = python or re.search(r'\b(import|def|self|print|from)\b| = ', recent)
            return -0.06 if code else 0.19
        return 0.05 if python else 0.33 if s.startswith(' ') else 0.44
    if t.startswith('[][]'):
        return -0.09
    if re.search(r'^[\"\']?\]+[\"\']?\[', t):
        return 0.82
    if t.startswith('}') and re.search(r'}[.$-]?\$?{', t):
        return 0.71
    if not t.startswith('(') and ')(' in t:
        return 0.62
    if re.search(r'\)[*+-]\(', t):
        return 0.42
    if re.search(r'[\])][\'\"]?\[', t):
        return 0.63
    for join, value in JOINS:
        if join in t:
            return value
    if t.startswith('<img'):
        return 1.1 if first or recent.endswith('<|endoftext|>') else 0.28
    if t == '.Printf':       # Go formatted output
        return 0.77
    if t.lower() == 'covid':
        return 0.71
    name = t.lstrip('._=').lower()
    if name in IDENTIFIERS:
        return IDENTIFIERS[name]
    if t == '[@':
        return 0.34
    if t == '://':
        return 0.12
    if t.isdecimal() or not t:
        return 0.0
    if t.startswith('.') and t[1:].isalpha():
        return 0.02
    return 0.004


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    recent, python = ('', False) if first else carry[1:]
    s = prefix.token_strings[-1]
    value = activation(s, recent, first, python)
    recent = (recent + s)[-120:]
    if re.search(r'(^|\n)\s*(import |from \w+ import |def )', recent):
        python = True
    return (doc, recent, python), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 677 (layers.0.mlp.down_proj:677).

Plain-language job: it is a small "glue punctuation" detector for technical text. It
fires on a symbol token that joins two pieces of one compound token, with no space
between them, and stays quiet on ordinary words and spaces. The main cases:

  * Literal UTF-8 byte escapes written out as text: "\\xc", "\\xe", "\\xa", "\\xb"
    (as in "\\xc2\\xa0"), and HTML numeric entities such as "&#" (strongest).
  * Bracket joins with no letters between them: "][", "}{", ")(", "](", as in
    arr[i][j], \\frac{a}{b}, f(x)(y).
  * C++ namespace "::" (std::cos, glm::normalize), moderate.
  * "#" used as a link anchor or fragment, e.g. "](#" or "{#": strong; "#" at the
    start of a line (a comment or heading) is weak.
  * A hyphen in a fixed compound name: "UTF-8" and "COVID-19" (strong), and the word
    COVID itself (moderate).

Everything else predicts 0. The values are rough class means of the measured
activation, not fitted weights. Context is the previous token only, so it is causal.
"""

READS = ()

BYTE_ESCAPES = {"\\xc", "\\xe", "\\xa", "\\xb"}
COVID_WORDS = {"COVID", " COVID", "Covid", " Covid"}
UTF_WORDS = {"utf", "UTF", "covid", "COVID", " COVID", "Covid", " Covid"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if token in BYTE_ESCAPES or "&#" in token:
        return None, 1.0
    if has_bracket_join(token):
        return None, 0.55
    if token == "::":
        return None, 0.4
    if token == "-" and prev in UTF_WORDS:
        return None, 1.0
    if token in COVID_WORDS:
        return None, 0.7
    if token == "[@":
        return None, 0.4
    if token == "#include":
        return None, 0.45
    if token.count("#") == 1:
        return None, hash_value(prev)
    return None, 0.0


def has_bracket_join(token):
    """A closing bracket directly followed by an opening one, with no letters or spaces."""
    return (
        any(a + b in token for a in ")]}" for b in "([{")
        and not any(c.isalnum() or c == " " for c in token)
    )


def hash_value(prev):
    """'#' after an opening bracket or a word is a link anchor or fragment (strong);
    at the start of a line it is a comment or heading (weak)."""
    if "\n" in prev or prev.strip() == "":
        return 0.1
    if prev[-1:] in ("(", "{", "[", ")", "}", "]") or prev[-1:].isalnum():
        return 0.8
    return 0.3

