"""Respond to short lowercase letter fragments, especially an attached 's'.

Numbers and capitals strongly boost 's' (seconds, decades, acronym plurals).
Other one-letter fragments and inflectional endings have weaker responses;
a longer lowercase fragment in the preceding token usually reduces them.
A few script-level letter classes and conversation boundary markers get
fixed responses. Unsupported tokens are zero: this describes the spelling-
related part, not every small lexical fluctuation of the component.
"""
import unicodedata

READS = ()
# Profiles: after capital, digit, accented lowercase, boundary;
# then intercept and length penalty after an ordinary lowercase stem.
VOWEL_PROFILES = {
    'o': (0.39, 0.25, 0.28, 0.16, 0.22, 0.030),
    'e': (0.36, 0.17, 0.22, 0.09, 0.08, 0.030),
    'a': (0.20, 0.07, 0.07, -0.01, 0.11, 0.030),
}
ENDING_PROFILES = {
    'er': (0.21, 0.17, 0.15, 0.10, 0.09, 0.012),
    'en': (0.24, 0.14, 0.15, 0.055, 0.18, 0.043),
    'es': (0.20, 0.17, 0.09, 0.06, 0.09, 0.030),
    'ed': (0.11, 0.05, 0.12, -0.01, 0.045, 0.009),
    'ing': (0.08, 0.02, 0.03, 0.01, 0.015, 0.000),
}
MARKERS = {
    '<think>': 0.156,
    '</think>': -0.054,
    '<tool_call>': -0.035,
    '</tool_call>': -0.082,
    '<|im_start|>': -0.035,
    '<|im_end|>': -0.029,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in MARKERS:
        return None, MARKERS[token]
    if len(token) == 1 and not token.isascii():
        if token in 'аеиоуы':
            return None, 0.085  # Common Cyrillic vowel fragments.
        if token in 'яюё':
            return None, -0.06  # Iotated Cyrillic vowels.
        if token in 'اوي':
            return None, 0.17  # Arabic long-vowel letters.
        if token in 'لمر':
            return None, 0.11  # Arabic liquids and the nasal m.
        if token == 'ن':
            return None, 0.21  # Arabic nasal n.
        if token == 'ς':
            return None, 0.08  # Greek word-final sigma.
        name = unicodedata.name(token, '')
        if token.islower() and name.startswith('LATIN'):
            return None, -0.025
        return None, 0.0
    single = len(token) == 1 and 'a' <= token <= 'z'
    if not single and token not in ENDING_PROFILES:
        return None, 0.0
    previous = ''
    if len(prefix.token_ids) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
    last = previous[-1:]
    length = min(len(previous.split()[-1]), 6) if previous.strip() else 0
    if token == 's':
        if not previous:
            value = 0.39
        elif last.isdigit():
            value = 0.55
        elif last.isupper():
            value = 0.60
        elif last.islower():
            value = 0.32 if not last.isascii() else (
                0.35 if length <= 2 else 0.24 if length == 3 else 0.12)
        else:
            value = 0.19
        return None, value
    if token in VOWEL_PROFILES:
        profile = VOWEL_PROFILES[token]
    elif token in ENDING_PROFILES:
        profile = ENDING_PROFILES[token]
    elif token in 'iu':
        profile = (0.25, 0.12, 0.18, 0.035, 0.10, 0.018)
    elif token in 'dlmnryt':
        # Nasals, liquids, dental stops, and y.
        profile = (0.21, 0.09, 0.12, 0.01, 0.11, 0.020)
    else:
        profile = (0.10, 0.04, 0.04, -0.028, 0.027, 0.012)
    capital, digit, accented, boundary, base, penalty = profile
    if previous.endswith('\\'):
        value = -0.02  # Escapes are not ordinary word continuations.
    elif last.isupper():
        value = capital
    elif last.isdigit():
        value = digit
    elif last.islower():
        value = base - penalty * length if last.isascii() else accented
    else:
        value = boundary
    return None, value

