"""Predict the positive pulse on a separate lowercase ``s`` suffix.

It is especially strong when ``s`` follows a digit or uppercase letter, as in
plural abbreviations and number-plus-s forms. Other positions are left at zero.
"""
READS = ()


def step(carry, prefix, upstream):
    if prefix.token_strings[-1] != "s":
        return None, 0.0

    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].rstrip()

    if previous and previous[-1].isdigit():
        return None, 0.56
    if previous and previous[-1].isupper():
        return None, 0.64
    if previous and previous[-1].islower():
        if prefix.token_strings[-2][:1].isspace():
            return None, 0.12
        return None, 0.20
    return None, 0.18

