"""Negative lexical evidence for disciplines, methods, and system structure.

The response is strongest for technology, architecture, methodology, and the
scientific suffix -ology. Related fields, procedures and systems respond more
weakly. Split scientific suffixes use the preceding word stem, resetting at
document boundaries. These are token-level cues, not a judgment about the
sentence's topic. Whole-word adjectives such as 'biological' have only a small
response. Unlisted tokens return zero; small idiosyncratic effects are omitted.
"""
import re

READS = ()
WORD_END = re.compile(r"[^\W\d_]+$")

STRONG_FIELDS = {'topology', 'morphology'}
OLOGY_FIELDS = {'terminology', 'mythology', 'pathology', 'physiology', 'ecology'}
FIELDS = {'biology', 'psychology', 'ontology', 'philosophy', 'taxonomy',
          'geometry', 'geography', 'metabolism', 'theology', 'ideology'}
SYSTEM_STRUCTURE = {'algorithm', 'algorithms', 'structure', 'mechanism',
                    'protocol', 'protocols', 'infrastructure', 'functionality'}
METHODS_AND_SYSTEMS = {'strategy', 'strategies', 'therapy', 'therapies',
                      'surgery', 'surgeries', 'machinery', 'logic', 'religion',
                      'dynamics', 'kinetics', 'hierarchy', 'mechanisms',
                      'structures', 'genetics', 'chemistry', 'democracy',
                      'microscopy', 'paradigm', 'anatomy', 'anthropology'}
TECHNICAL_TERMS = {'technique', 'techniques', 'procedure', 'procedures', 'legislation',
              'framework', 'frameworks', 'vocabulary', 'semantics', 'imagery',
              'verdict', 'genotype', 'assay', 'electronics'}
TECHNICAL_TRANSLATIONS = {'技术', '技術', '科技', '工艺', '工藝', '架构', '架構',
                          '机制', '機制', '策略', '算法'}


def token_value(raw, stem=""):
    word = raw.strip(' \n\t_.-/').lower()
    if word == 'strategy':
        return -1.15
    if word == 'technology':
        return -3.5
    if word == 'technologies':
        return -2.9
    if word == 'methodology':
        return -3.2
    if word == 'methodologies':
        return -2.2
    if word == 'architecture':
        return -2.9
    if word == 'architectures':
        return -1.8
    if word in STRONG_FIELDS:
        return -3.3
    # A split scientific ending retains information from its preceding stem.
    if word in {'ology', 'ologies'}:
        if stem.endswith('method'):
            return -4.8
        if stem.endswith(('top', 'morph')):
            return -4.2
        if stem.endswith('hist'):
            return -3.6
        if word == 'ologies' and stem in {'ap', 'anth'}:
            return -1.3
        return -2.9
    if word in {'ological', 'ologically'}:
        value = -1.0
        if stem.endswith('morph'):
            value = -2.5
        elif stem.endswith(('top', 'hist', 'method', 'techn')):
            value = -1.95
        elif stem.endswith(('ont', 'neuropsych', 'phenomen')):
            value = -1.5
        return value + (0.2 if word == 'ologically' else 0.0)
    if word in {'ologie', 'atology'}:
        return -2.3
    if word in {'iology', 'ologia', 'ologi', 'ología', 'otechnology'}:
        return -1.8
    if word in {'alogy', 'ология', 'ологии'}:
        return -1.5
    if word in {'logy', 'onomy', 'icism'}:
        return -1.0
    if word in OLOGY_FIELDS:
        return -2.0
    if word in FIELDS:
        return -1.5
    if word in SYSTEM_STRUCTURE or word == 'technological':
        return -1.15
    if word in METHODS_AND_SYSTEMS or word in TECHNICAL_TRANSLATIONS:
        return -0.85
    if word in {'ologist', 'ologists', 'ography', 'ographies', 'ogenesis',
                'orphism', 'urgery', 'olog', 'ogy', 'ometry'}:
        return -0.85
    if word in TECHNICAL_TERMS or word in {'ectomy', 'metry', 'tecn', 'ategies'}:
        return -0.65
    if word in {'tech', 'hardware', 'physics', 'statistics', 'agriculture',
                'economy', 'symmetry', 'apparatus', 'syndrome', 'schema',
                'metadata', 'workflow'}:
        return -0.45
    if word in {'ality', 'ism'}:
        return -0.35
    if word.startswith('технолог'):
        return -2.0
    if word.endswith(('ological', 'ologically')):
        return -0.25
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous_word = carry[1] if carry and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    stem = previous_word.lower() if raw[:1].isalpha() else ''
    value = token_value(raw, stem)
    match = WORD_END.search(previous_word + raw)
    word = match.group()[-40:] if match else ''
    return (doc, word), value

