"""Candidate 4: a memory word (forget, remember, reset, recall, memory, ...) in English, Chinese,
Japanese or Vietnamese, and the function word right after it ("forget to", "remember that",
"reminder of", "memories of"). Everything else is predicted as 0."""
READS = ()


def memory_value(token):
    """How strongly one token is a memory word, from about 0 to 6."""
    w = token.strip(" ._").lower()
    if w.startswith(("forget", "forgot")) or "忘" in w:
        return 4.0 if w.isascii() else 6.0
    if w.startswith("reset") and not w.startswith("resett"):
        return 3.4
    if w.startswith(("remember", "remind", "recall")):
        return 2.0
    if any(k in w for k in ("记忆", "回忆", "记得", "记住", "铭记", "牢记", "想起", "忆", "憶", "nhớ")):
        return 1.7
    if w.startswith("refresh"):
        return 1.6
    if w.startswith("memor"):
        return 0.8
    if w.startswith(("retriev", "restor")):
        return 0.6
    if w == "wait":
        return 0.4
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if memory_value(token) > 0:
        return carry, memory_value(token)
    if memory_value(before) >= 0.8 and token.strip().lower() in ("of", "to", "that", "me"):
        return carry, 0.9
    return carry, 0.0

