PACE = {
    "soon", "late", "slow", "fast", "quick", "rapid", "delay", "duration",
    "timing", "occasional", "gradual",
}
MANNER = {
    "easy", "eager", "gentle", "smooth", "rough", "quiet", "odd", "peaceful",
    "flow", "fluent", "hesitate", "diminish",
}
DEGREE = {
    "weak", "strong", "slight", "short", "long", "partial", "few", "final",
    "expensive", "passive", "efficient", "chronological",
}
OTHER_SCRIPTS = {"быстр", "долг", "最终", "流畅", "不断", "很快", "紧紧", "느"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    old_doc, old_word = carry if carry is not None else (None, "")
    word = "" if doc != old_doc or token[:1].isspace() else old_word
    piece = "".join(ch for ch in token if ch.isalpha()).lower()
    word = word + piece if piece else ""
    english = any(word.startswith(term) for term in PACE | MANNER | DEGREE)
    other = any(piece.startswith(term) for term in OTHER_SCRIPTS)
