        return -0.62
    if lower in ("immersed", "immersion", "immersive", "inund"):
        return -0.45
    if lower in ("foam", "swim", "turbulent", "turbulence", "detergent"):
        return -0.44
    if lower in ("swimming", "floating", "splash", "soap", "sponge", "bath"):
        return -0.3
    if lower == "christmas":
        if word[0].isupper():
            return 2.6 if token[:1].isspace() else 1.85
        return 1.45
    if lower in ("birthday", "birthdays", "thanksgiving", "halloween"):
        return 1.2 if lower != "halloween" else 1.5
    if lower in ("easter", "anniversary", "festive", "claus"):
        return 0.4
    if lower in ("holiday", "holidays", "festival", "festivals", "celebrate"):
        return 0.25
    if word in (
        "生日", "新年", "春节", "元旦", "节日", "礼品", "礼物", "誕"
    ):
        return {"生日": 0.8, "新年": 1.0, "礼品": 0.75,
                "礼物": 0.5, "誕": 0.4, "春节": 1.1,
                "元旦": 1.5, "节日": 0.75}[word]
    if word in ("浸泡", "泡泡", "泡沫", "一波"):
        return {"浸泡": -3.9, "泡泡": -3.6, "泡沫": -1.75, "一波": -1.25}[word]
    for characters, value in NEGATIVE_CHARACTERS:
        if any(char in characters for char in word):
            return value if len(word) == 1 else value * (0.46 / len(word))
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, "", 0.0)
    _, previous, previous_value = carry
    token = prefix.token_strings[-1]
    # A byte fragment can finish a character that was undecodable alone.
    if "\ufffd" in token:
        completed = prefix.text_prefixes[-1][-1:]
        if completed and completed != "\ufffd":
            token = completed
    word = token.strip().lower()
    value = lexical_value(token)
    if previous_value < -0.3 and word == "of":
        value += 0.5 * previous_value
    if (previous in ("rins", "wash", "inund")
            and word in ("ed", "ing", "es", "ated", "ating")):
        value = -0.65 if previous == "inund" else -0.45
    if word in ("ubble", "ubbles") and previous in ("b", "bubble"):
        value = -1.1 if word == "ubble" else -1.65
    if word == "alloween" and previous == "h":
        value = 1.0
    return (document, word, lexical_value(token)), float(value)

