WORD_CLASSES = (
    ({'getaddress', 'setaddress'}, -4.1),
    ({'sockaddr'}, -2.7),
    ({'地址', '址'}, -4.95),                  # Chinese address
    ({'адрес'}, -3.3),                      # Russian address
    ({'adres', 'adresse', 'adress'}, -2.1),  # European address spellings
    ({'direccion', 'dirección', '网址'}, -1.2),
    ({'für', 'voor', 'för', 'для'}, -0.32),  # Translations of 'for'
    ({'thereof'}, -0.75),
    ({'href'}, -1.0),                       # Web link destination
    ({'handle', 'handles'}, -1.0),
    ({'handled', 'handling', '处理', '治理'}, -0.63),
    ({'tackle', 'tackles', 'tackled', 'tackling'}, -1.6),
    ({'remedy', 'remedies', '解决', '解决了'}, -0.95),
)
WORD_RESPONSE = {w: v for words, v in WORD_CLASSES for w in words}


def verb_stem(word):
    for ending in ('ing', 'ed', 's'):
        if word.endswith(ending):
            return word[:-len(ending)]
    return word


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    plain = word.lstrip('._/(-<').lower()
    preceding = prev.strip().lower()
    root = verb_stem(preceding)
    value = WORD_RESPONSE.get(plain, 0.0)
    if plain in ADDRESS:
        value = -4.75
        if token == ' address':
            if preceding in {'ip', 'email', 'e-mail'}:
                value = -3.5
            elif preceding == 'to':
                value = -5.45
        elif word.startswith('('):
            value = -3.6
    elif plain == 'addr':
        value = -5.1 if word.startswith('_') or word == 'Addr' else -4.45
    elif plain == 'for':
        value = -0.65 if token.startswith(' ') else -0.78
        if token == ' for':
            value = -0.5
            if root == 'ask' or preceding in {'responsible', 'grateful'}:
                value = 0.22
            elif root in {'look', 'search', 'seek', 'request', 'account', 'stand'}:
                value = 0.0
            elif root == 'allow' or preceding in {'reason', 'reasons'}:
                value = -0.11
            elif root == 'need' or preceding in {
                'used', 'required', 'waiting', 'except'
            }:
                value = -0.27
            elif preceding in {'known', 'available', 'necessary', 'important'}:
                value = -0.35
            elif prev.isspace():
                value = -0.70
    elif plain in {'url', 'urls'}:
        value = -0.7 if word[0].isupper() else -0.35
    elif preceding == 'address' and value == 0.0:
        if token == ' of':
            value = -2.45
        elif token == ' the':
            value = -0.95
        elif word in {'ed', 'ing', 'es'}:
            value = -4.2 if word == 'ed' else -4.9
    return (doc, token), value

"""Approximate activation using doubled-letter spelling patterns.

Short nn fragments and the German surname ending -mann get strong negative
values. Longer fragments usually get smaller values; case, leading spaces,
and letters around nn refine them. Cyrillic нн and Latin mm are weaker.
A lowercase initial n repeating the previous token's final n is also weakly
negative. The announce family is negative; military/warfare and spaced
law/lawful are positive. Otherwise predict zero. Reset context per document.
This omits token-specific and longer-range contextual variation.
"""
READS = ()


def doubled_n(raw, text):
    i = text.find('nn')
    after = len(text) - i - 2
    title = raw.strip().istitle()
    if text.endswith('mann'):
        if len(text) == 4 and title:
            return -3.4
        return -4.8 / (1.0 + 0.55 * (len(text) - 4))
    if len(text) <= 3:
        if i and text[i-1] == 'a':
            return -3.9 if title else -5.0
        return -3.8 if text == 'enn' else -3.2
    if len(text) == 4:
        if raw[:1].isspace():
            return -2.8 if title and text.endswith('ann') else -1.8
        if text.startswith('ann'):
            return -3.3 if text[-1] in 'aeiy' else -1.3
        return -2.3
    if text.startswith('announ'):
        return -1.9
    if len(text) == 5:
        return -0.6 if raw[:1].isspace() else -1.5
    if after == 0:
        return -1.9
    return -0.8 if after == 1 and text[i-1:i] == 'a' else -0.25


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    text = raw.strip().lower()
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    value = 0.0
    if 'nn' in text:
        value = doubled_n(raw, text)
    elif 'нн' in text:
        if len(text) <= 4:
            value = -1.2
        else:
            value = -0.55 if len(text) == 5 else -0.1
    elif 'mm' in text:
        i = text.find('mm')
        if len(text) > 5:
            value = -0.1
        elif i and text[i-1] == 'o':
            value = -1.1 if text.endswith('mm') else -0.3
        else:
            value = -0.15 if raw.strip().istitle() else -0.5
    elif raw.startswith('n') and previous.lower().endswith('n'):
        if len(raw) <= 2:
            value = -0.75
        else:
            value = -0.6 if len(raw) == 3 else -0.4
        if len(raw) > 4:
            value = -0.2
    elif text in {'military', 'warfare'}:
        value = 1.2
    elif text in {'law', 'lawful'} and raw[:1].isspace():
        value = 0.6
    return (doc, raw), value

