"""A current-token spelling detector, not a single semantic category.

The words 'within' and 'void' give strong positive values; a small class
of enclosure words gives weaker ones. Doubled c gives a strong negative
value that shrinks with surrounding letters, with adjustments for case,
spacing, punctuation, and a few preceding vowels. Longer c runs and some
other doubled-consonant or c-rich fragments give smaller negative values.
All other tokens give zero. There is no dependence on earlier tokens.
"""
import math

ENCLOSURE_WORDS = {'inside', 'wherein', 'scope', 'scoped',
                   'framework', 'enclosed', 'restrict'}

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().strip('()[]{}<>.,;:\'"_/')
    lower = word.lower()
    value = 0.0
    if lower == 'within':
        value = 1.42 if token.startswith(' ') else 1.11
        if word[0].isupper():
            value *= 0.66
    elif lower == 'void':
        value = 1.92 if token == ' void' else 1.18
        if token.startswith(('<', '(')):
            value = 1.0
        elif token.startswith('\t'):
            value = 1.42
        if word[0].isupper():
            value *= 0.46
    elif lower in ENCLOSURE_WORDS and token.startswith(' '):
        value = 0.33
    elif len(lower) > 2 and set(lower) == {'c'}:
        value = -2.2
    elif 'cc' in lower:
        at = lower.index('cc')
        after = len(lower) - at - 2
        value = -4.7 * math.exp(-0.55 * at - 1.3 * after)
        if after == 0 and at == 1:
            if lower[0] == 'a' and (token != word or word[0].isupper()):
                value *= 0.62
            elif lower[0] == 'o':
                value *= 0.70
            elif lower[0] == 'u':
                value *= 1.65
        if lower == 'cc':
            if token.startswith(' '):
                value = -4.2
            elif word == 'Cc':
                value = -3.0
        if token.startswith(('(', '.')):
            value *= 0.65
    elif lower in ('idd', 'udd'):
        value = -0.8
    elif len(lower) == 2 and lower[0] == lower[1]:
        if lower == 'dd':
            value = -0.8
        elif lower[0] in 'bfgjkmnpqrz':
            value = -0.2
    elif lower in ('conc', 'cic'):
        value = -1.2 if token.startswith(' ') else -0.85
    elif word == 'Mc':
        value = -0.5
    return None, value

