        elif word.startswith(('_', '-', '$')):
            value = 0.85
        elif word.startswith(('.', '/')):
            value = 1.3
        elif token == 'Data':
            value = 1.35
        else:
            value = 1.22 if token.startswith(' ') else 1.06
    elif lower == 'daten':
        value = 0.58
    elif word in DATA_TRANSLATIONS:
        value = DATA_TRANSLATIONS[word]
    elif lower == 'metadata':
        value = 0.3
    elif lower == 'dataframe':
        value = 0.15
    elif bare.endswith('Data') and bare.isidentifier():
        value = 0.45
    else:
        value = 0.0

    if len(prefix.token_strings) > 1 and (
        prefix.document_ids[-2] == prefix.document_ids[-1]
    ):
        previous_token = prefix.token_strings[-2]
        previous = word_in(previous_token).lower()
