auxiliaries and ordinary words raise a graded prose score; digits, whitespace
and closing brackets lower it. Symbol classes have different response strengths
and thresholds. Selected document-opening words, headings and source markers
get a separate positive prediction. Unhandled token shapes predict zero.

This deliberately omits token-specific lexical variation and uses only the
current and previous token, not a full mathematics or source-code parser.
"""
READS = ()

PREPOSITIONS = frozenset(
    'of in on at for from with by to into over under about through between '
    'before after without within across against around during near'.split())
AUXILIARIES = frozenset(
    'is are was were be been being have has had do does did can could may '
    'might will would shall should must'.split())
FUNCTION_WORDS = frozenset(
    'and or but nor so yet I you he she it we they me him her us them this '
    'that these those which who what whose a an'.split())


def prose_score(token):
    s = token.strip()
    if not s:
        return 0.0
    if s.endswith('`'):
        return -0.12
    word = s.lower()
    if word == 'the':
        return 1.05
    if token[:1].isspace() or token[:1].isupper():
        if word in PREPOSITIONS:
            return 0.90 if word in {'to', 'from', 'by'} else 1.03
        if word in AUXILIARIES:
            return 0.95
        if s in FUNCTION_WORDS or word in FUNCTION_WORDS:
            return 0.82
        if (word.endswith('ing') and len(word) > 4 and word != 'string') or word == 'use':
            return 1.03
    if s[-1].isdigit():
        return -0.40
    if s[-1].isalpha():
        if len(s) == 1 and s.isascii():
            return -0.5
        if s.isupper() and s.isascii():
            return 0.49
        return 0.80 if s.isalpha() and s.isascii() and token[:1].isspace() else 0.63
    if s[-1] in ',:=':
        return 0.60
    if s[-1] in ')]}\"\'':
        return -0.17
    if s[-1] in '-+*/|&<>':
        return 0.46
    if s[-1] == '.':
        return -0.1 if token.startswith(' ') else 0.35
    return 0.10 if s[-1] in '([{;' else 0.33


def opening_value(token):
    if token == 'The':
        return 1.20
    if token in {'#', '##', '###', '#include', 'import'}:
        return 1.10
    if token in {'What', 'When', 'Where', 'Why', 'How', 'Is', 'Can', 'Does'}:
        return 1.0
    if token in {'This', 'That', 'These', 'Those', 'An', 'In', 'If', 'Are'}:
        return 0.55
    return 0.75 if token in {'using', '//', '/*'} else 0.0


# Baseline, response strength and prose-score offset for symbol classes.
RESPONSES = (
    ('$', (-0.17, 0.61, 0.55)),
    ('_', (-0.37, 1.34, -0.21)),
    ('./', (-0.16, 1.70, -0.14)),
    ('\\<@*#[', (0.00, 1.90, -0.28)),
    ('\"\'‘“«', (0.08, 1.25, -0.22)),
    ('(—', (0.03, 4.80, -0.67)),
    ('%', (-0.13, 0.70, 0.00)),
    ('!?,;', (0.02, 1.00, -0.20)),
    ('-|&~^', (0.02, 0.90, -0.20)),
    (':+=>{}', (0.02, 0.80, -0.38)),
)


def notation_value(token, score):
    if not token.startswith(' ') or not token.strip():
        return 0.0
    s = token.strip()
    ch = s[0]
    if ch == '`' and not s.startswith('``'):
        return -0.30 - 2.0 * max(score, -0.08)
    if s.startswith('``'):
        response = (0.08, 1.25, -0.22)
    elif s.startswith('__'):
        response = (0.09, 0.20, 1.34)
    elif ch in '/<' and len(s) > 1:
        response = (0.07, 0.25, 0.20)
    elif ch == '$' and len(s) > 1:
        response = (-0.06, 0.52, 0.50)
    elif ch == '\\' and len(s) > 1:
        response = (0.04, 1.09, -0.06)
    elif ch == '.' and len(s) > 1:
        return 0.0
    else:
        response = next((r for symbols, r in RESPONSES if ch in symbols), None)
    if response is None:
        return 0.0
    baseline, gain, offset = response
    return baseline - gain * max(score + offset, 0.0) ** 2


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    first = (len(prefix.token_ids) == 1 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    value = opening_value(token) if first else notation_value(
        token, prose_score(prefix.token_strings[-2]))
    return None, float(value)

programs.haiku:
"""Candidate 2: markup symbols that open inline code or LaTeX math in running prose."""
READS = ()

STRONG = {"`": (-1.9, -0.7), "$": (-1.2, -0.5)}   # (after a word, after anything else)
WEAK = "_/.\\'*<[#%@|\""                          # other markup-like symbols
WEAK_WORD = -0.4                                  # weak symbols, only after a word
DOC_START = 0.2                                   # first token of a new document

def _is_word(s):
    return s.strip().isalpha()

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    value = 0.0
    if prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
        after_word = _is_word(prev)
        t = s.strip()
        if s.startswith(" ") and t:
            if t[0] in STRONG:
                value += STRONG[t[0]][0 if after_word else 1]
            elif t[0] in WEAK and after_word:
                value += WEAK_WORD
        if prev == "<|endoftext|>":
            value += DOC_START
    return carry, float(value)

programs.luna:
"""Give small negative scores to punctuation-like token openings.

Common quotation, bracket, and code/math marks get a slightly larger score;
other Unicode punctuation and symbols get a weaker one.  This is a crude
lexical cue, not a reconstruction of the full component response.
"""

import unicodedata

READS = ()
SYNTAX_MARKS = frozenset("\"'`()[]{}$@\\~|<>_-/;!*%+=")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lstrip()
    if token:
        if token[0] in SYNTAX_MARKS:
            return None, -0.036
        if unicodedata.category(token[0])[0] in "PS":
            return None, -0.012
    return None, 0.0

"""Approximate the small negative response to language about making an idea clear."""

READS = ()

# Word families for understanding, insight, and explanation, including common Chinese terms.
CORE = ("understand", "insight", "explain", "reveal", "discover", "认识", "理解")
RELATED = ("interpret", "study", "clarif", "elucidat", "comprehend", "认知")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()
    doc = prefix.document_ids[-1]
    previous = () if carry is None or carry[0] != doc else carry[1]

    phrase = (
        "into" in token and any("insight" in word for word in previous[-1:])
    ) or (
        "light" in token and any("shed" in word for word in previous[-1:])
    ) or (
        "on" in token and bool(previous) and "light" in previous[-1]
    )
    if phrase or any(root in token for root in CORE):
        value = -0.24
    elif any(root in token for root in RELATED):
        value = -0.10
    else:
        value = 0.0

    carry = (doc, (previous + (token,))[-2:])
    return carry, float(value)

programs.haiku:
"""Layer-0 MLP unit 694 (down_proj), as a readable rule.

It is mostly silent. It goes negative in short-form dates and clock times, as they appear in
forum and comment metadata: "Sep 16 '13 at 15:20", "Joined: 02 Sep 2009", "Posted ... AM",
"47 views" followed by "###". The strongest dips are on the space after an abbreviated month,
on "at" and "AM"/"PM" after a date, on "views" and on the "###" that follows a view count.
"Originally Posted by" dips too. Weaker positive nudges go to the words "answer" and "github". Predicts 0 elsewhere.
"""

READS = ()

ABBR_MONTHS = {"Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"}
FORUM_LABELS = {"Joined", "Posts", "Posted", "Reading", "Tags", "Replies", "Moderator", "Member", "Hi", "ago"}


def is_date_context(recent):
    """A month abbreviation, AM/PM, 'views', or several single digits in the last 12 tokens."""
    digits = sum(t.isdigit() for t in recent)
    return digits >= 3 or any(t in ABBR_MONTHS or t in ("AM", "PM", "views") for t in recent)


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    tok = raw.strip()
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    prev2 = prefix.token_strings[-3].strip() if len(prefix) > 2 else ""
    recent = [t.strip() for t in prefix.token_strings[-13:-1]]
    dated = is_date_context(recent)
    value = 0.0
    if raw == " " and prev in ABBR_MONTHS:
        value = -1.0                      # the space before the day or year: "Sep 16"
    elif tok in ABBR_MONTHS:
        value = -0.3
    elif tok in ("AM", "PM", "am", "pm"):
        value = -0.7 if dated else 0.0
    elif tok in ("at", "AT"):
        value = -0.5 if dated else 0.0
    elif tok == ":":
        if prev in ("Re", "Joined", "Posts"):
            value = -1.4                  # "Joined:", "Posts:", "Re:" labels
        elif prev.isdigit() and prev2.isdigit():
            value = -0.5                  # the colon in a clock time, "15:20"
        elif dated:
            value = -0.1
    elif tok == "views":
        value = -1.3
    elif tok == "###":
        value = -3.0 if "views" in recent else -0.4
    elif tok in FORUM_LABELS:
        value = -0.7
    elif tok == "by" and prev == "Posted":
        value = -2.0                      # "Originally Posted by"
    elif tok in ("answer", "answers", "github"):
        value = 0.2                       # weak positive nudge
    return carry, float(value)

programs.luna:
"""Mark compact date/time notation and a few familiar web-page labels."""
import re

READS = ()

MONTH = (
    r"(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|"
    r"jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|"
    r"oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)"
)
NUMBER = r"\d[\d,]*(?:\.\d+)?"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    before = "" if carry is None or carry[0] != document else carry[1]
    tail = before[-80:]
    clean = tail.rstrip()
    word = token.strip().lower()
    next_carry = (document, (before + token)[-80:])

    def pulse(size):
        return next_carry, -0.2 * size

    # Separators in clocks, dates, and short metadata labels.
    if token.strip() == ":":
        if re.search(r"\d\s*:\s*\d(?:\d\s*)?$", clean):
            return pulse(0.65)
        if re.search(r"\d$", clean):
            return pulse(0.4)
        if re.search(r"(?:\bq|\bjoined)$", clean, re.I):
            return pulse(0.8)
    if token.strip() == ",":
        if re.search(r"\d{1,2}\s+" + MONTH + r"$", clean, re.I):
            return pulse(0.8)
        if re.search(r"\d{1,2}$", clean):
            return pulse(0.45)
    if token.strip() == "." and re.search(
        r"\b(?:jan|feb|mar|apr|jun|jul|aug|sep|oct|nov|dec)$", clean, re.I
    ):
        return pulse(0.45)
    if token == " " and re.search(r"\b" + MONTH + r"$", clean, re.I):
        return pulse(0.5)
    if word in {"am", "pm"} and re.search(r"(?:\d\s*:\s*\d{2}|\d{1,2})$", clean):
        return pulse(0.65)
    if token.strip() in {"\n", "\n\n"} and re.search(r"\b\d{4}$", clean):
        return pulse(0.3)

    # Forum and help-page cues, only in their usual short context.
    if word == "edited" and re.search(r"last\s*$", clean, re.I):
        return pulse(0.8)
    if word == "by" and (re.search(r"answer\s*$", clean, re.I) or
                          re.search(r"\d{1,3}$", clean)):
        return pulse(0.9)
    amount = r"(?:" + NUMBER + r"|" + MONTH + r"\s+\d{1,2})$"
    if word == "at" and re.search(amount, clean, re.I):
        return pulse(0.7)
    if word == "hi" and (tail.endswith("\n") or
                          re.search(r"\d{1,2}:\d{2}$", clean)):
        return pulse(0.65)
    if word == "views" and re.search(r"\d$", clean):
        return pulse(0.65)
    if word == "online" and re.search(r"try\s+it$", clean, re.I):
        return pulse(0.65)
    if word == "syntax" and re.search(r"detailed$", clean, re.I):
        return pulse(0.4)
    if word == "level" and re.search(r"challenge$", clean, re.I):
        return pulse(0.65)

    # Common symbols and markup used in technical/web text.
    if token.strip().lower().endswith(".com") or token.strip() == "±":
        return pulse(0.65)
    if token.strip() == "---" or token.strip().startswith("##"):
        return pulse(0.45)
    return next_carry, 0.0

programs.sol:
"""A negative detector for reversal and the related Latin vers/vert stems.

Reversal/inversion are strongest; verse, traversal, universality, versions,
and conversion have successively smaller responses. Selected direction and
travel words give weaker responses, as do several East Asian, Russian and
Vietnamese reversal words. A small state joins split stems and
continues their response on inflections and on following of/the/to. It resets
at document boundaries. Unlisted tokens are zero unless this local continuation
rule applies.
The different inflections are kept separate because their observed strengths
are quite different, even when their meanings are closely related. There is
also a small negative response to selected severity/chronicity words.
"""
import re

READS = ()
ENDING_FACTORS = {
    'ely': 0.75, 'es': 0.7, 'ed': 0.6, 'ing': 0.75,
    'als': 0.6, 'ity': 0.43, 'al': 0.35, 'er': 0.3,
    'a': 0.25, 'o': 0.2, 'e': 0.25, 'en': 0.15,
}
LINK_FACTORS = {'of': 0.55, 'the': 0.2, 'to': 0.13}


def clean_title(token):
    return token.strip().strip('._').istitle()


def lexical_score(token):
    word = token.strip().strip('._/()[]{}:`"\'<>-').lower()
    spaced = token.startswith((' ', '\n', '\t'))
    if word == 'reverse':
        if token.startswith('_'):
            return -4.9
        if clean_title(token):
            return -6.0
        return -6.8 if spaced else -6.3
    if word == 'inverse':
        if token.startswith('_'):
            return -4.1
        return -5.5 if spaced else -4.65
    if word in {'revers', 'invers', 'adverse', 'averse'}:
        return -4.65
    if word in {'reversed', 'reversal', 'converse'}:
        return -3.9
    if word == 'versed':
        return -4.2
    if word in {'advers', 'verse', 'vers'}:
        if word == 'verse' and not spaced:
            return -4.3
        return -3.15
    if word == 'iverse':
        return -2.7
    if word in {'verses', 'adversely', 'adversity', 'convers',
                'conversely', 'traversal', 'aversal'}:
        return -2.4
    if word in {'travers', 'traverse'}:
        return -3.0
    if word == 'avers':
        return -2.3
    if word in {'univers', 'universal', 'universally', 'iversal',
                'versa', 'verso', 'irreversible'}:
        return -1.65
    if word in {'version', 'versión'}:
        return -1.24 if spaced else -1.0
    if word in {'universe', 'versatile', 'versatility', 'invert', 'inverted',
                'inversion', 'revert', 'backwards', 'opposite'}:
        return -1.05
    if word in {'versions', 'vert', 'divers', 'diverse', 'versus', 'travel',
                'parallel', 'undo'}:
        return -0.75
    if word in {'convert', 'conversion', 'vertical', 'vertically', 'vertex',
                'vertices', 'backward', 'contrary', 'reciprocal', 'piv',
                'pivot', 'flip', 'route', 'journey'}:
        return -0.57
    if word in {'traveled', 'travels', 'diversity', 'reverted', 'converting',
                'clockwise', 'counterclockwise', 'trajectory'}:
        return -0.4
    if word == '逆':
        return -7.0
    if word in {'逆转', '逆転'}:
        return -3.5
    if word == '역':
        return -3.5 if spaced else -1.05
    if word in {'順', '顺'}:
        return -1.8
    if word == '翻':
        return -1.3
    if word in {'反', '倒'}:
        return -1.15
    if word in {'反之', '竖'}:
        return -1.25
    if word in {'返', '反而'}:
        return -0.8
    if word in {'版本', '版', '垂直', '旅行', '旅'}:
        return -0.75
    if word in {'severe', 'severity', 'chronic', 'chron'}:
        return -0.55
    if word in {'recurrence', 'iterate', 'alternate', 'upside'}:
        return -0.65
    if word in {'iterative', 'rearr'}:
        return -0.4
    # Detached word endings with the same letters as the turning stem.
    if word in {'ers', 'ors', 'ivers'}:
        return {'ers': -0.28, 'ors': -0.16, 'ivers': -0.7}[word]
    if word in {'dfs', 'bfs'}:
        return -0.65  # Depth/breadth-first graph traversal.
    if word == 'ngược':
        return -2.3  # Vietnamese: opposite/reversed.
    if word == 'универс':
        return -2.0
    if word == 'вер':
        return -0.75 if spaced else -0.35
    if word.startswith('обрат'):
        return -1.4
    if word.startswith('перев'):
        return -0.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous_word, previous_score = '', 0.0
    else:
        _, previous_word, previous_score = carry
    score = lexical_score(token)
    clean = token.strip().strip('._/()[]{}:`"\'<>-')
    word = clean.lower()

    # Recover a stem split between tokens, e.g. re + verse or tr + avers.
    initial = re.match(r'[A-Za-z]+', token)
    joined = word
    if initial:
        joined = previous_word + initial.group().lower()
    if word in {'verse', 'vers', 'versed', 'avers', 'ivers', 'ers'}:
        if joined.startswith('revers'):
            score = -6.9 if word == 'verse' else -4.8
        elif joined.startswith('invers'):
            score = -5.8 if word == 'verse' else -4.7
        elif joined.startswith(('transvers', 'irrevers')):
            score = -4.0 if word == 'verse' else -3.6
        elif joined.startswith('convers'):
            score = -5.4 if word == 'verse' else -4.4
        elif joined.startswith('travers'):
            score = -3.0
        elif joined.startswith('attravers'):
            score = -1.7
        elif 'univers' in joined:
            score = -1.6
        elif 'divers' in joined:
            score = -1.1 if word == 'ers' else -0.75
        elif joined.endswith('solvers'):
            score = -0.4

    # Inflectional endings can continue a response begun on the stem.
    if not token[:1].isspace() and previous_score < -0.7:
        suffix_factor = ENDING_FACTORS.get(word)
        if suffix_factor is not None:
            if word == 'es' and previous_word.startswith('revers'):
                suffix_factor = 0.88
            score += suffix_factor * previous_score
    # The grammatical link in "inverse of", "version of", "reverse the".
    if token[:1].isspace():
        link_factor = LINK_FACTORS.get(word, 0.0)
        score += link_factor * previous_score

    last_word = re.search(r'[A-Za-z]+$', token)
    if last_word:
        if last_word.start() == 0:
            next_word = (previous_word + last_word.group().lower())[-32:]
        else:
            next_word = last_word.group().lower()
    else:
        next_word = ''
    next_score = score
    if token[:1].isspace() and word in LINK_FACTORS:
        next_score = 0.0
    return (doc, next_word, next_score), float(score)

"""Approximate an English indefinite-noun-phrase and degree signal.

Give large positive responses to a/an followed by degree words or adjectives,
strongest for 'a more'. Plain noun heads are weaker or negative. Recognize
quantifying 'of' phrases and a weaker second modifier after the article.
Adjective vocabulary and productive endings provide the lexical distinction;
capitalization and token boundaries adjust its strength. Reset at documents.
Many small, word-specific background activations are deliberately omitted.
"""
READS = ()

DEGREE = {'more': 4.6, 'much': 3.45, 'very': 2.8}
INTENSIFIERS = set('''
    less pretty quite truly totally completely particularly purely merely
'''.split())
DEGREE_ADVERBS = set('''
    rather really too significantly somewhat fairly extremely absolutely
    especially equally incredibly overly remarkably visually far genuinely
    fundamentally slightly highly relatively fully entirely even
'''.split())
EVALUATION = set('good great better valid'.split())
CERTAINTY = set('clear real full complete possible different'.split())
EMPHASIS = set('''
    true genuine fundamental relevant keen strict distinct mere
'''.split())
HIGH_LOW = set('high low higher lower greater'.split())
QUALITY = set('''
    strong long quick fast early natural similar unique direct double
    excellent interesting nice bad suitable valuable easy further well deep
    timely thorough slow close promising accurate efficient mixed
    correct known sufficient pertinent fair poor mighty precise diverse
    fascinating exciting refreshing balanced combined modified contrasting
    awesome amazing compelling challenging striking misleading ongoing rich
'''.split())
ADJECTIVES = set('''
    able absolute acute adequate alternate appropriate big binary black
    brief bright broad broken certain cheap clean clever common complex
    constant convenient cool custom dark decent difficult dry dull extra
    extreme false familiar fine finite former free fresh fun gentle
    given grim happy hard healthy heavy honest hot huge important key
    large last lasting late latter left light linear living loose major
    maximum mean minimum modern modest multiple necessary new newer
    novel odd old open particular past perfect popular prime prominent
    proper pure random rare recent red regular right robust safe secure
    senior separate severe sharp short significant simple single small
    smart smooth solid standard steady straight straightforward
    surprising tall tight tiny top tough upper warm weak wet white whole
    wide world young zero
'''.split())
QUANTITY = set('one two three four five first half'.split())
GRADABLE = set('''
    high low large small big long short wide broad deep strong weak quick fast
    bright dark clean healthy mean
    slow close clear good bad full new old young late early cheap rich poor
    warm cool hot tight nice easy simple happy heavy light sharp
'''.split())
DOCUMENT_NOUNS = set('''
    movie article book list user video website report image song file
'''.split())
BARE_NOUNS = set('''
    car equation line table row circle month year issue meeting student
    collection building block array village object team question story class
    organization man person woman child pair group point function field vector
    relation statement range string link vehicle name company graph triangle
    signal trial proposal arrival animal festival hospital journal canal
    family butterfly assembly reply anomaly capital
'''.split())
PHRASE_HEADS = {
    'kind': 2.8, 'sort': 2.6, 'bit': 1.05, 'way': 1.15,
    'sense': 1.0, 'matter': 0.9, 'type': 0.8, 'form': 0.8,
    'degree': 0.8, 'lot': 0.57,
}
OF_HEADS = {
    'lots': 0.65,
    'variety': 0.72, 'number': 0.53, 'sense': 0.55,
    'degree': 0.5, 'couple': 0.23,
}


def modifier(word):
    if word in DEGREE:
        return DEGREE[word]
    if word in INTENSIFIERS:
        return 2.3
    if word in DEGREE_ADVERBS:
        return 1.7
    if word in EVALUATION:
        return 2.2 if word != 'better' else 2.6
    if word in CERTAINTY:
        return 2.05 if word != 'different' else 2.3
    if word in EMPHASIS:
        return 2.0
    if word in HIGH_LOW:
        return 1.85
    if word in QUALITY:
        return 1.5
    if word in PHRASE_HEADS:
        return PHRASE_HEADS[word]
    if word.endswith('er'):
        stem = word[:-2]
        candidates = (stem, stem + 'e', stem[:-1] + 'y', stem[:-1])
        for base in candidates:
            if base in GRADABLE:
                return modifier(base) + 0.25
    if word == 'single':
        return 0.1
    if word in {'lesser', 'worse'}:
        return 1.5
    if word in DOCUMENT_NOUNS:
        return -0.65
    if word in BARE_NOUNS:
        return -0.3
    if word == 'particular':
        return 0.35
    if word == 'second':
        return 0.5
    if word in ADJECTIVES or word in QUANTITY:
        return 1.0
    if word == 'little':
        return 0.84
    if word == 'few':
        return -0.55
    if word in {'non', 'un', 'multi', 'self'}:
        return 0.65
    if len(word) > 4 and word.isalpha() and word.endswith(
        ('ous', 'ive', 'able', 'ible', 'ful', 'less', 'ical', 'ic', 'al', 'ed')
    ):
        return 0.65
    if len(word) >= 5 and word.isalpha() and word.endswith('ly'):
        return 1.0
    return -0.05


def of_phrase(head, determiner):
    """The linker in phrases such as 'a kind of' and 'a number of'."""
    if head in {'kind', 'sort'}:
        if determiner == 'a':
            return 3.3 if head == 'kind' else 3.7
        return 2.0 if determiner == 'some' else 1.0
    if head in {'type', 'form', 'way'}:
        if determiner == 'a':
            return {'type': 1.8, 'form': 1.45, 'way': 1.0}[head]
        return 0.35
    if head in {'kinds', 'sorts'}:
        return 0.6
    if head in {'full', 'much', 'plenty', 'something'}:
        return 0.5
    if head == 'number' and determiner != 'a':
        return 0.15
    return {'terms': 0.68, 'bit': 0.95, 'lot': 0.97}.get(
        head, OF_HEADS.get(head, 0.0)
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    start = carry is None or carry[0] != doc
    if start:
        previous, before, article_scale, previous_raw = '', '', 0.0, ''
        value = 1.8 if raw == ' a' else 1.7 if raw == ' an' else 0.0
    else:
        _, previous, before, article_scale, previous_raw = carry
        value = 0.0
        if word == 'more':
            value = 0.68
            if previous == 'much' and before == 'a':
                value = 2.4
        elif word == 'few':
            value = -0.4
        elif word == 'of':
            value = of_phrase(previous, before)
        elif word == 'terms' and previous == 'in':
            value = 0.5
        if before in {'a', 'an'} and not article_scale and word != 'of':
            strength = modifier(word) if raw.startswith(' ') else 0.0
            if strength > 0:
                value = max(value, 0.2 * strength)
        if article_scale:
            horizontal_space = raw.isspace() and '\n' not in raw
            if horizontal_space or word in {'"', "'", '“', '$', '`'}:
                value = 0.65
            elif raw.startswith(' ') and word:
                value = modifier(word)
                if value == -0.05 and raw.strip()[:1].isupper():
                    value = 0.15
            value *= article_scale
    # A bare a/an can be a fragment of a word, rather than an article.
    boundary = start or raw[:1].isspace() or not previous_raw[-1:].isalpha()
    scale = 0.0
    if word in {'a', 'an'} and boundary:
        if raw.strip()[:1].isupper():
            scale = 0.78
        else:
            scale = 0.6 if not raw[:1].isspace() else 1.0
    return (doc, word, previous, scale, raw), float(value)

programs.luna:
"""Pick out adjective-like words after “a/an” and familiar degree words.

Strong contexts often show a descriptive continuation after an indefinite
article; degree words such as “more” also occur in other modifier phrases.
This is a short lexical and phrase-position approximation, not a POS tagger.
"""
READS = ()

DEGREE_WORDS = frozenset({
    "more", "most", "less", "least", "very", "quite", "rather",
    "particularly", "especially", "highly", "further", "much", "bit",
})

ADJECTIVES = frozenset({
    "common", "standard", "prominent", "high", "great", "competitive",
    "simple", "alternative", "general", "quick", "large", "new",
    "right", "zero", "dark", "legal", "well", "expanded", "diverging",
})

ADJECTIVE_ENDINGS = (
    "able", "ible", "al", "ary", "ent", "ant", "ful", "less",
    "ive", "ous", "ic", "ed", "ing", "est",
)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if not word or not word[0].isalpha():
        return None, 0.0

    if word in DEGREE_WORDS:
        return None, 0.55

    if len(prefix.token_strings) < 2:
        return None, 0.0
    same_doc = prefix.document_ids[-1] == prefix.document_ids[-2]
    previous = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if previous in {"a", "an"}:
        if word in ADJECTIVES or (len(word) >= 4 and word.endswith(ADJECTIVE_ENDINGS)):
            return None, 0.55
    return None, 0.0

programs.sol:
"""Predict separator pulses, not a lookup of individual token activations.

Causally important training examples were mostly separators. A standalone
newline uses a line-length pulse, strengthened by recent short lines and
weakened by indentation. Single spaces and nonbreaking spaces
following short digit-ending or one-character alphabetic items also get
negative predictions. Sub/sup spellings, numeric markup boundaries and
Chinese enumeration commas have explicit rules. Remaining non-whitespace
tokens predict 0.002.

The numerical constants were fitted to training activations with modest
causal-importance weighting. Stored line text is capped at 256 characters.
Recent-line length starts at 50. At newline-bearing tokens, it mixes
0.6 old / 0.4 last closed line. History resets at row and document starts.
"""
from math import exp

READS = ()
ENUMERATION_NUMERALS = frozenset("一二三四五六七八九十百")


def whitespace_value(token, previous, line, recent, starts_document):
    clean = line.strip()
    words = clean.split()
    word = words[-1] if words else ''
    digit = previous[-1:].isdigit()
    letter = previous[-1:].isalpha()
    single_letter = len(word) == 1 and word.isalpha()
    length = len(word)

    if token in ('\n', '\n\n'):
        double = token == '\n\n'
        short = exp(-len(clean) / 8.0) * (0.8 if double else 1.0)
        isolated_word = clean.replace('_', '').isalnum()
        indented = len(line) - len(line.lstrip()) > 1
        pulse = (0.295 + 0.906 * exp(-recent / 24.0)
                 + 0.118 * digit + 0.093 * single_letter
                 + 0.161 * isolated_word - 0.584 * indented)
        return (0.074 + 0.033 * double - 0.127 * digit
                - 0.049 * letter - short * pulse
                - 0.289 * starts_document)

    if token == ' ':
        if digit:
            return -0.532 if length <= 2 else (
                -0.481 if length == 3 else -0.235)
        return -0.238 if single_letter else 0.002

    if token == '\xa0':
        if digit:
            return -0.425 if length <= 2 else (
                -0.277 if length == 3 else -0.259)
        return -0.086 if single_letter else 0.035

    if token == ' \n':
        if digit:
            return -0.625 if length <= 3 else -0.309
        if single_letter:
            return -0.642
        if previous.endswith('\ufffd'):
            return -0.50
        return -0.02

    if '\n' in token:
        return -0.10 if single_letter else 0.015

    # Multiple spaces and tab-containing gaps differ from single spaces.
    if digit:
        return -0.18 if len(clean) > 20 else -0.02
    if single_letter:
        return -0.05
    if word.isalpha():
        return 0.13 if len(clean) <= 24 else 0.04
    return 0.009


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    starts_document = carry is None or carry[0] != doc
    if starts_document:
        previous, line, recent = '', '', 50.0
    else:
        _, previous, line, recent = carry
    token = prefix.token_strings[-1]

    if token.isspace():
        value = whitespace_value(token, previous, line, recent, starts_document)
    elif token in ('.sub', '.sup'):
        # Stronger after short symbols, as in chemical sub/sup notation.
        value = -0.75 if len(previous.strip()) <= 2 else -0.27
    elif previous[-1:].isdigit() and token in ('sub', 'sup', '**', '</'):
        # Number followed by notation, a bold/power marker, or a closing tag.
        value = -0.18 if token == '</' else -0.40
    elif token == '、':
        if previous[-1:].isdigit():
            value = -0.55
        elif previous[-1:] in ENUMERATION_NUMERALS:
            value = -0.20
        else:
            value = 0.02
    else:
        value = 0.002

    if '\n' in token:
        parts = (line + token).split('\n')
        recent = 0.6 * recent + 0.4 * len(parts[-2].strip())
        line = parts[-1][-256:]
    else:
        line = (line + token)[-256:]
    return (doc, token, line, recent), float(value)

programs.luna:
"""Recognize rare tokens for abstract/document-description language.

The strongest signal is the word abstract itself; a weaker signal marks
document-outline labels and several words beginning with abs- or extr-.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if "abstract" in token:
        return None, 6.3
    if token.startswith(("abs", "extr")):
        return None, 0.65
    if token.strip(".,:;!?*_#-/\\()[]{} ") in {
        "summary", "description", "introduction", "readme",
    }:
        return None, 0.75
    return None, 0.0

programs.sol:
"""Short written ik/ик fragments give a strong negative response.

Extra letters and a leading word boundary usually weaken it. This is
not a general /ick/ sound detector: the spelling and token boundaries
matter. Other short k-syllables are weaker triggers, especially after
an i/y in the previous token. Unmatched text is predicted as zero.
"""
import unicodedata

READS = ()
CYRILLIC = str.maketrans({'и': 'i', 'і': 'i', 'ы': 'y', 'к': 'k',
                         'а': 'a', 'е': 'e', 'у': 'u', 'о': 'o', 'й': 'y'})
# Relative strengths of vowels immediately following the written ik.
TAIL_VOWELS = {'a': 0.7, 'e': 0.3, 'i': 0.4, 'o': 0.5, 'u': 0.5}
LIKE_FORMS = {'like', 'likes', 'likely', 'unlikely', 'unlike'}
K_LETTERS = set('कكکκきキ')
OTHER_IK = {'يك', 'ิก'}  # Arabic yeh-kaf, Thai short-i plus ko kai.


def spelling(text):
    text = text.lower().translate(CYRILLIC)
    return ''.join(c for c in unicodedata.normalize('NFD', text)
                   if not unicodedata.combining(c))


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    s = spelling(raw.strip())
    boundary = raw[:1].isspace()
    cyrillic = 'к' in raw.lower()
    value = 0.0
    if s in LIKE_FORMS or s == 'ikke':  # Danish/Norwegian 'not'.
        value = -0.04
    elif s == 'likelihood':
        value = -0.8
    elif 'ik' in s and s.isalpha() and len(s) <= 8:
        left, tail = s.split('ik', 1)
        if len(left) <= 3:
            value = -3.6 if cyrillic else -4.45
            if left:
                value *= (0.6 if cyrillic else 0.68)
                value /= 1 + 0.25 * (len(left) - 1)
            if tail:
                factor = TAIL_VOWELS.get(tail[0], 0.4)
                if cyrillic and tail == 'i':
                    factor = 0.65
                if cyrillic and tail == 'a':
                    factor = 0.75
                if len(tail) > 1 and tail[0] == 'e':
                    factor *= 1.3
                if len(tail) > 1 and tail[0] == 'i':
                    factor *= 0.5
                if tail == 'k':
                    factor = 0.72
                if len(tail) > 1 and tail[0] == 'a':
                    factor *= 0.5
                value *= factor / (1 + 0.4 * max(0, len(tail) - 2))
            if boundary and not raw.strip().isupper():
                value *= 0.55 if not left else 0.85
    elif s in {'k', 'ka', 'ki', 'ke', 'ko', 'ku'} and not boundary:
        previous = ''
        if len(prefix.token_ids) > 1:
            if prefix.document_ids[-1] == prefix.document_ids[-2]:
                previous = spelling(prefix.token_strings[-2])[-1:]
        value = -0.2 if previous.isalpha() else 0.08
        if previous in {'i', 'y', 'ı'}:
            value = -1.6 if previous == 'i' else -1.0
            if s == 'ki':
                value *= 0.8
        elif previous in {'e', 'u', 'o', 'l', 'r'}:
            value = -0.35
        if s == 'ke' and not cyrillic:
            value *= 0.45
    elif s == 'k' and boundary:
        value = 0.25 if cyrillic else 0.05
    elif len(s) <= 3 and s.isalpha() and 'k' in s:
        if s.endswith(('ek', 'uk')) or s in {'eks', 'uki', 'uka'}:
            value = -0.3 if cyrillic else -0.65
        elif s.endswith(('yk', 'ık')):
            value = -1.4
        elif len(s) == 2 and s.endswith('k') and s[0] not in 'aeiouscс':
            value = -0.6
        elif s.endswith(('ak', 'ok')) and not boundary:
            value = -0.2
    elif s.startswith('iq') and len(s) <= 6:
        value = -1.0 if len(s) <= 3 else -0.6
    if not boundary and raw in K_LETTERS:
        value = -0.5
    if raw in OTHER_IK:
        value = -1.8
    return None, float(value)

programs.luna:
"""Estimate the sparse negative response to short K-sound word pieces.
Strong harvested examples are often brief fragments of names and multilingual
words, so this deliberately ignores longer tokens and ordinary soft-c spellings.
"""
READS = ()
KANA_K = set("かきくけこカキクケコ")


def has_k_sound(text):
    s = text.lower()
    for i, ch in enumerate(s):
        if ch in "kqкκकㄱㅋ" or ch in KANA_K:
            return True
        if ch == "c" and i + 1 < len(s) and s[i + 1] in "aou":
            return True
    return False


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if len(token.strip()) <= 4 and has_k_sound(token):
        return None, -0.1
    return None, 0.0

programs.sol:
"""Detect compact empty delimiters and closing braces.

The strongest cue is an empty curly-brace pair, whether an empty object or a
format placeholder. Empty square brackets, self-closing markup and closing
braces are weaker cues. Quotes, attached punctuation and the previous twelve
tokens adjust these responses; recent context resets between documents.
Unmodeled lexical responses are left at zero.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = () if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    previous = ''.join(recent)
    value = 0.0
    if '{}' in token:
        before, after = token.split('{}', 1)
        value = 6.9
        if token.startswith(' '):
            value += 0.3
        if before.rstrip().endswith(('"', "'")):
            value += 1.0
        if after.startswith(('"', "'")):
            value -= 2.3
        elif after.startswith(')'):
            value -= 1.1
        if '\n' in token:
            value -= 1.0
        if previous.endswith((']', 'interface')):
            value -= 2.2
    elif '[]' in token:
        value = 0.9
        if ',' in token or ';' in token or token.startswith('([]'):
            value += 0.5
    elif '/>' in token:
        value = 1.3
    elif token == '{"':
        value = 0.55
    elif token == '{':
        value = -0.1
    elif '}' in token:
        value = 0.5
        if token.startswith(' '):
            value += 0.3
        if '"}' in token or "'}" in token or '}}' in token:
            value += 0.4
        if '\n' in token:
            value -= 0.15
        if re.search(r'\\[A-Za-z]+|\^|_', previous[-35:]):
            value -= 0.3
        if previous.endswith('\n'):
            value += 0.35
        if '}(' in token:
            value -= 0.55
    return (doc, (recent + (token,))[-12:]), float(value)

