programs.sol:
"""Recognize guide/guard spellings and words for guidance in several languages.

Responses are strongest for 'guide' and the guid- stem (also in GUID
identifiers), weaker for inflections, guard, and the short ambiguous gu- stem.
A few literal Chinese/Japanese forms of guide and guidance are recognized.
Leading spaces, capitalization, and affixes change the response strength.
Split inflections, such as Guid + ed, also fire at their ending token.
The preceding token is forgotten at document boundaries. Everything else
is predicted as zero; this is not a semantic classifier of whole sentences.
"""
READS = ()


def lexical_value(token):
    text = token.strip()
    word = text.lstrip('_-(/.').lower()
    spaced = token.startswith(' ')
    if word == 'guide':
        value = 4.7 if spaced else 5.8
        if spaced and text[:1].isupper():
            value += 0.3
    elif word == 'uide':
        value = 3.8
    elif word == 'guid':
        value = 3.4 if spaced else 4.8
        if spaced and text[:1].isupper():
            value += 0.5
    elif word == 'guides':
        value = 4.0
    elif word in {'guided', 'guiding'}:
        value = 3.4
    elif word == 'guidance':
        value = 2.1
    elif word in {'guideline', 'guidelines'}:
        value = 1.4
    elif word == 'guard':
        value = 3.2 if spaced else 3.7
    elif word == 'guards':
        value = 3.2 if text[:1].isupper() else 2.5
    elif word in {'guarded', 'guarding', 'uard', 'guar'}:
        value = 2.0
    elif word in {'guardian', 'guardians', 'guarda', 'guardar'}:
        value = 1.5
    elif word == 'gu':
        value = 2.3 if spaced or text[:1].isupper() else 1.7
    elif word == 'gui':
        value = 0.85 if text.isupper() else 1.3
    elif word == 'guinea':
        value = 1.8
    elif text in {'导', '導', '指导'}:
        value = 3.4
    elif text == 'ガイド':
        value = 4.9
    elif text in {'指南', '导师'}:
        value = 2.4
    elif text == '指引':
        value = 1.4
    else:
        value = 0.0
    return value


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = lexical_value(token)
    root = previous.strip().lstrip('_-(/.').lower()
    if root == 'guid' and token in {'ed', 'es', 'ing', 'ance'}:
        value = 0.9 * lexical_value(previous + token)
    elif root == 'guid' and token in {'eline', 'elines'}:
        value = 0.6 * lexical_value(previous + token)
    elif root == 'guard' and token in {'ed', 'ing', 'ian', 'ians'}:
        value = 0.9 * lexical_value(previous + token)
    return (doc, token), float(value)

programs.haiku:
"""Guide / guard word detector for layers.0.mlp.down_proj:703.

This component fires on the word "guide" and its relatives. Its activation is large
and positive on the current token when that token is part of a "guide" word:
"guide", " Guide", "guides", "guided", "guiding", "_GUID" (a code identifier), and the
Chinese words for guiding (导, 導, 指导, 引导). Weaker responses come from "guidance"
and "guidelines", from "guard" words, from the bare fragments "gu" / "gui" / "guar"
that start a split word, and from a few role words that lead or steer someone
(escort, pilot, navigate, judge, shield). Words that only look similar (guitar, gun,
guess, guy, guest, guarantee) stay near zero, and so does 导致 ("lead to").

The program looks only at the newest token, so it is stateless. Its value is the
component's activation on that token, in rough units taken from the training data.
"""

READS = ()

GUIDE_CHINESE = {"导", "導", "指导", "指導", "引导", "导师", "指南"}
ROLE_WORDS = {"escort", "pilot", "navigate", "judge", "judges", "judged", "shield"}
FRAGMENTS = {"gu", "gui", "guar"}


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    if word.startswith("guidance") or word.startswith("guideline"):
        value = 2.0          # "guidance", "guidelines": weaker than "guide" itself
    elif "guid" in word or word in GUIDE_CHINESE:
        value = 4.5          # "guide", "guides", "guided", "guiding", "_GUID", 导, 指导
    elif word.startswith("guard"):
        value = 3.0          # "guard", "guards", "guarded"
    elif word in FRAGMENTS:
        value = 2.0          # split pieces of guide/guard words
    elif word in ROLE_WORDS:
        value = 1.0
    else:
        value = 0.0
    return carry, float(value)
